    function osxI18nNode(node) {
        const p = node.parentElement;
        if (!p) return;
        const tag = p.tagName;
        if (tag === 'SCRIPT' || tag === 'STYLE' || tag === 'TEXTAREA' || p.isContentEditable) return;
        const raw = node.nodeValue, t = raw && raw.trim();
        if (t && OSX_I18N_EN[t]) node.nodeValue = raw.replace(t, OSX_I18N_EN[t]);
    }
    function osxI18nApply(root) {
        if (!OSX_EN || !root) return;
        try {
            if (root.nodeType === 3) { osxI18nNode(root); return; }
            if (root.nodeType !== 1) return;
            const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, {
                acceptNode(node) {
                    const p = node.parentElement;
                    if (!p) return NodeFilter.FILTER_REJECT;
                    const tag = p.tagName;
                    if (tag === 'SCRIPT' || tag === 'STYLE' || tag === 'TEXTAREA' || p.isContentEditable) return NodeFilter.FILTER_REJECT;
                    return OSX_I18N_EN[node.nodeValue.trim()] ? NodeFilter.FILTER_ACCEPT : NodeFilter.FILTER_SKIP;
                }
            });
            const nodes = [];
            while (walker.nextNode()) nodes.push(walker.currentNode);
            for (const n of nodes) osxI18nNode(n);
            const els = root.querySelectorAll('[placeholder],[title]');
            for (const el of els) {
                const ph = el.getAttribute('placeholder');
                if (ph && OSX_I18N_EN[ph.trim()]) el.setAttribute('placeholder', OSX_I18N_EN[ph.trim()]);
                const ti = el.getAttribute('title');
                if (ti && OSX_I18N_EN[ti.trim()]) el.setAttribute('title', OSX_I18N_EN[ti.trim()]);
            }
        } catch (e) { osxDbg('i18n.apply', e); }
    }
    function osxI18nStart() {
        if (!OSX_EN) return;
        try {
            document.querySelectorAll('[id^="os-"]').forEach((el) => osxI18nApply(el));
            const mo = new MutationObserver((recs) => {
                for (const r of recs) {
                    if (r.type === 'characterData') osxI18nNode(r.target);
                    if (r.addedNodes) r.addedNodes.forEach((n) => { if (n.nodeType === 1) osxI18nApply(n); else if (n.nodeType === 3) osxI18nNode(n); });
                }
            });
            mo.observe(document.body, { childList: true, subtree: true, characterData: true });
        } catch (e) { osxDbg('i18n.start', e); }
    }
    osxI18nStart();

    // ---- v1.2.0：「最新の日付シートを確認」の対象キーワード（空欄＝すべての xlsx/xlsm） ----
    const OSX_SHEET_KW_KEY = 'osx_sheet_keyword_v1';

    // ---- v11.15.1：窓の一覧を作り直しても、スクロール位置を先頭に戻さない ----
    // 使い方：x.replaceChildren() の代わりに osxClearKeep(x)。作り直す前にスクロール位置を覚え、作り直しが終わった直後（同じ処理の中で追加し終わったあと）に戻す。
    //  ・覚えるのは、x 自身と、x を含む親たちのスクロール位置、および x の中にある（作り直しで消える）スクロール領域（位置は「何番目の子か」の並びで対応づける）。
    //  ・一覧が短くなった場合はブラウザが下端に丸めるだけ。失敗しても何も起きない（通常の作り直しと同じ）。
    function osxScrollSave(target) {
        const snap = { target, anc: [], desc: [] };
        try {
            for (let n = target; n && n !== document.body && n !== document.documentElement; n = n.parentElement) { if (n.scrollTop > 0) snap.anc.push([n, n.scrollTop]); }
            const path = (el) => { const p = []; for (let n = el; n && n !== target; n = n.parentElement) p.push(Array.prototype.indexOf.call(n.parentElement.children, n)); return p.reverse(); };
            const els = target.querySelectorAll('*');
            for (let i = 0; i < els.length; i++) { if (els[i].scrollTop > 0) snap.desc.push([path(els[i]), els[i].scrollTop]); }
        } catch (e) { osxDbg('scroll.save', e); }
        return snap;
    }
    function osxScrollRestore(snap) {
        if (!snap || (!snap.anc.length && !snap.desc.length)) return;
        const apply = () => {
            try {
                snap.anc.forEach(([n, t]) => { if (n.isConnected && Math.abs(n.scrollTop - t) > 1) n.scrollTop = t; });
                snap.desc.forEach(([p, t]) => {
                    let e = snap.target;
                    for (let i = 0; i < p.length && e; i++) e = e.children[p[i]];
                    if (e && e !== snap.target && Math.abs(e.scrollTop - t) > 1) e.scrollTop = t;
                });
            } catch (e) { osxDbg('scroll.restore', e); }
        };
        Promise.resolve().then(apply);        // 同じ処理の中で中身を追加し終わった直後
        if (typeof requestAnimationFrame === 'function') requestAnimationFrame(apply);   // 念のため、描画の直前にもう一度
    }
    function osxClearKeep(target) { const snap = osxScrollSave(target); target.replaceChildren(); osxScrollRestore(snap); }

    // ---- v9.167：カテゴリごとの色分け（見出し・左の縦線・カテゴリ全体の薄い背景）----
    // ・色はこのブラウザだけに保存（テーマとは別。テーマを変えても色分けは残る）。色分けはテーマの「上に重ねる」だけで、形・壁紙・演出には触らない
    // ・色は最初に自動で割り当てる（使われていない色を優先）。🎨で変えたものだけ手動（m:1）。「自動」で戻せる
    const OSX_CATCOL_KEY = 'osDesktopCategoryColors_v1';
    const OSX_FIRSTPACK_KEY = 'osx_firstpack_v1';   // v11.36.0：1stパックの案内を済ませたか（履歴扱い）      // { カテゴリ名: { c:'#rrggbb', m:0|1 } }
    const OSX_CATCOL_ON_KEY = 'osDesktopCategoryColorOn_v1';  // 色分けを使うか（既定ON）
    const OSX_CATCOL_LVL_KEY = 'osDesktopCategoryColorLvl_v1'; // 背景の濃さ 0=弱 1=中 2=強（既定 中）
    const OSX_CATCOL_OTHER = 'その他';
    const OSX_CATCOL_PALETTE = ['#ef4444', '#f97316', '#eab308', '#22c55e', '#14b8a6', '#38bdf8', '#6366f1', '#a855f7', '#ec4899'];
    const OSX_CATCOL_LEVELS = [['弱', 0.09], ['中', 0.16], ['強', 0.26]];
    let osxCatColors = (() => { const o = osxLs.getJson(OSX_CATCOL_KEY, {}); return o && typeof o === 'object' && !Array.isArray(o) ? o : {}; })();
    let osxCatColorOn = osxLs.getFlag(OSX_CATCOL_ON_KEY, true);
    let osxCatColorLvl = (() => { const v = parseInt(osxLs.get(OSX_CATCOL_LVL_KEY, '1'), 10); return v >= 0 && v < OSX_CATCOL_LEVELS.length ? v : 1; })();
    let osxCatColDirty = false;
    function osxCatHexRgb(h) { const m = /^#([0-9a-f]{6})$/i.exec(String(h || '')); if (!m) return null; const n = parseInt(m[1], 16); return [(n >> 16) & 255, (n >> 8) & 255, n & 255]; }
    function osxCatFg(h) {   // 見出しの文字色：背景が明るければ濃い色、暗ければ白
        const c = osxCatHexRgb(h); if (!c) return '#ffffff';
        const f = (v) => { v /= 255; return v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4); };
        return (0.2126 * f(c[0]) + 0.7152 * f(c[1]) + 0.0722 * f(c[2])) > 0.35 ? '#0f172a' : '#ffffff';
    }
    function osxCatColorsSave() { osxCatColDirty = false; osxLs.setJson(OSX_CATCOL_KEY, osxCatColors); }
    function osxCatColorsFlush() { if (osxCatColDirty) osxCatColorsSave(); }
    // カテゴリの色を返す（色分けOFFなら null）。未設定なら、いま存在するカテゴリで使われていない色を割り当てて覚える
    function osxCatColorOf(cat, allCats) {
        if (!osxCatColorOn) return null;
        const e = osxCatColors[cat];
        if (e && osxCatHexRgb(e.c)) return e.c;
        if (cat === OSX_CATCOL_OTHER) return '#94a3b8';
        const used = {};
        (allCats || []).forEach((k) => { const x = osxCatColors[k]; if (x && x.c) used[x.c] = (used[x.c] || 0) + 1; });
        let best = OSX_CATCOL_PALETTE[0], bn = Infinity;
        OSX_CATCOL_PALETTE.forEach((p) => { const n = used[p] || 0; if (n < bn) { bn = n; best = p; } });
        osxCatColors[cat] = { c: best, m: 0 };
        osxCatColDirty = true;
        return best;
    }
    function osxCatColorRename(old, nn) { const e = osxCatColors[old]; if (!e) return; if (!osxCatColors[nn]) osxCatColors[nn] = e; delete osxCatColors[old]; osxCatColorsSave(); }
    function osxCatColorForget(cat) { if (osxCatColors[cat]) { delete osxCatColors[cat]; osxCatColorsSave(); } }

