    // v11.9.0／v11.10.0：個人OneDrive（○○-my.sharepoint.com/personal/<ID>）への対応
    //   ・SharePoint内のOneDrive画面（sharepoint.aspx/onedrive/…）はフォルダを移動してもアドレスが変わらないため、
    //     現在のフォルダはアドレスから読めない → 最初は「ドキュメント」直下を表示し、以降は右エリアの操作（customCurrentFolderPath）で移動する
    //   ・個人OneDriveのID（/personal/<ID>）は、ページ内の文字列か通信履歴から探す。ドメインはテナント名から決める（○○ → ○○-my）
    const IS_OD_SHELL = /\/_layouts\/15\/sharepoint\.aspx\/onedrive(?:\/|$)/i.test(location.pathname);
    const IS_MY_HOST = /-my\.sharepoint\.com$/i.test(location.hostname);   // v11.11.0：OneDriveの通常画面（個人OneDrive側のページ）
    const OD_PERSONAL_KEY = 'osxOdPersonal_v1';
    const OD_PERSONAL_RE = /https:\/\/[a-z0-9-]+-my\.sharepoint\.com\/personal\/[A-Za-z0-9_.%~-]+/i;
    let odPersonalCache = '';
    let odRetryCount = 0;
    function odPersonalBase() {
        if (odPersonalCache) return odPersonalCache;
        let found = '';
        try {
            const m = document.documentElement.innerHTML.match(OD_PERSONAL_RE);
            if (m) found = m[0];
        } catch (e) { osxDbg('odPersonalBase html', e); }
        if (!found) {
            try {
                const hit = performance.getEntriesByType('resource').map((x) => x.name).find((n) => OD_PERSONAL_RE.test(n));
                if (hit) found = hit.match(OD_PERSONAL_RE)[0];
            } catch (e) { osxDbg('odPersonalBase perf', e); }
        }
        if (!found) {
            try { const s = localStorage.getItem(OD_PERSONAL_KEY); if (s && OD_PERSONAL_RE.test(s)) found = s; } catch (e) { osxDbg('odPersonalBase ls', e); }
        } else {
            try { localStorage.setItem(OD_PERSONAL_KEY, found); } catch (e) { osxDbg('odPersonalBase ls set', e); }
        }
        if (found) odPersonalCache = found;
        return found;
    }
    // SharePoint側（○○.sharepoint.com）のオリジン。個人OneDrive側のページから、サイト（/sites/…）を扱うときに使う
    function odSpOrigin() {
        return IS_MY_HOST ? location.origin.replace(/-my\.sharepoint\.com$/i, '.sharepoint.com') : location.origin;
    }
    function odMyOrigin() {
        if (IS_MY_HOST) return location.origin;
        const b = odPersonalBase();
        if (b) { try { return new URL(b).origin; } catch (e) { osxDbg('odMyOrigin', e); } }
        const m = /^([a-z0-9-]+)\.sharepoint\.com$/i.exec(location.hostname);
        return (m && !/-my$/i.test(m[1])) ? `https://${m[1]}-my.sharepoint.com` : '';
    }
