    function escapeHtml(s) {
        return String(s).replace(/[&<>"']/g, (c) => ({
            '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
        }[c]));
    }



    // v9.61：ライブラリ外のページ（サイトトップ等）用に、そのサイトの既定ドキュメントライブラリを
    // 取得してキャッシュする。値：siteUrl -> ライブラリのサーバー相対パス（取得失敗時はnull）。
    const defaultLibCache = new Map();
    const defaultLibPending = new Map();

    function ensureDefaultLibrary(siteUrl) {
        if (defaultLibCache.has(siteUrl)) return Promise.resolve(defaultLibCache.get(siteUrl));
        if (defaultLibPending.has(siteUrl)) return defaultLibPending.get(siteUrl);
        const task = (async () => {
            let found = null;
            try {
                const url = `${siteUrl}/_api/web/lists?$filter=BaseTemplate eq 101 and Hidden eq false`
                    + `&$select=Title,RootFolder/ServerRelativeUrl&$expand=RootFolder`;
                const data = await fetchJson(url);
                const rels = ((data && data.d && data.d.results) || [])
                    .map((l) => l && l.RootFolder && l.RootFolder.ServerRelativeUrl)
                    .filter(Boolean)
                    .filter((r) => !/\/(SiteAssets|Style Library|FormServerTemplates|SitePages|_catalogs)$/i.test(r));
                found = rels.find((r) => /\/(Shared Documents|Documents)$/i.test(r)) || rels[0] || null;
            } catch (e) {
                found = null;
            }
            defaultLibCache.set(siteUrl, found);
            defaultLibPending.delete(siteUrl);
            return found;
        })();
        defaultLibPending.set(siteUrl, task);
        return task;
    }

    function getSiteUrlFromPathname(pathname, origin) {
        const parts = pathname.split('/').filter(Boolean);
        // v11.9.0：個人OneDrive（/personal/<ID>）。SharePoint側の画面から呼ばれたときは、個人OneDrive側のドメインを使う
        if (parts.length >= 2 && parts[0] === 'personal') {
            let host = '';
            try { host = new URL(origin).hostname; } catch (e) { host = ''; }
            const myOrigin = /-my\.sharepoint\.com$/i.test(host) ? origin : (odMyOrigin() || origin);
            return `${myOrigin}/personal/${parts[1]}`;
        }
        // v11.11.0：個人OneDrive側のページから /sites/… を扱うときは、SharePoint側のドメインを使う
        if (IS_MY_HOST && parts.length >= 2 && (parts[0] === 'sites' || parts[0] === 'teams')) return `${odSpOrigin()}/${parts[0]}/${parts[1]}`;
        if (parts.length >= 2 && (parts[0] === 'sites' || parts[0] === 'teams')) {
            return `${origin}/${parts[0]}/${parts[1]}`;
        }
        return origin;
    }

    function decodeParam(value) {
        if (!value) return null;
        try { return decodeURIComponent(value); } catch (e) { return value; }
    }

    function guessAllItemsPath(folderPath) {
        const parts = String(folderPath || '').split('/').filter(Boolean);
        if (parts.length < 3) return null;
        return `/${parts[0]}/${parts[1]}/${parts[2]}/Forms/AllItems.aspx`;
    }

    function encodeServerRelativeUrl(path) {
        return String(path || '')
            .split('/')
            .map((seg, i) => (i === 0 && seg === '' ? '' : encodeURIComponent(seg)))
            .join('/');
    }

    function getCurrentFolderContext() {
        try {
            const u = new URL(location.href);
            const hashQuery = u.hash.replace(/^#/, '');
            const hashParams = new URLSearchParams(hashQuery.startsWith('?') ? hashQuery.slice(1) : hashQuery);

            const usingCustomPath = !!customCurrentFolderPath;

            let folderPath = customCurrentFolderPath || decodeParam(u.searchParams.get('id') || u.searchParams.get('RootFolder')
                || hashParams.get('id') || hashParams.get('RootFolder'));

            // customCurrentFolderPath（同一画面移動）が有効な間は、表示中のフォルダと
            // 実際のブラウザのアドレス（pathname／viewid）が一致していない可能性がある。
            // ここで実アドレスのpathnameやviewidをそのまま使い回すと、「移動元サイトの
            // AllItems.aspxパス」に「移動先フォルダのidパラメータ」を組み合わせた不整合な
            // アドレスが生成されてしまう（URLをコピー／通常画面に戻る等で誤ったURLになる
            // 原因）。そのため同一画面移動中は実アドレスを参照せず、移動先フォルダパスから
            // 必ず作り直す。
            let listViewPathname = (!usingCustomPath && /\/Forms\/AllItems\.aspx$/i.test(u.pathname)) ? u.pathname : null;
            const viewId = usingCustomPath ? null : (u.searchParams.get('viewid') || hashParams.get('viewid'));

            if (!folderPath && listViewPathname) {
                folderPath = decodeURIComponent(listViewPathname.replace(/\/Forms\/AllItems\.aspx$/i, ''));
            }

            if (!folderPath && !/\.aspx$/i.test(u.pathname)) {
                const parts = u.pathname.split('/').filter(Boolean);
                const third = (parts[2] || '').toLowerCase();
                if (parts.length >= 3 && (parts[0] === 'sites' || parts[0] === 'teams' || (IS_MY_HOST && parts[0] === 'personal')) && !SKIP_PATH_SEGMENTS.has(third)) {
                    folderPath = decodeURIComponent(u.pathname);
                }
            }

            // v11.9.0：SharePoint内のOneDrive画面は、アドレスから現在のフォルダが分からない。
            //   右エリアで移動した先（customCurrentFolderPath）があればそれ、なければ個人OneDriveの「ドキュメント」直下
            if (IS_OD_SHELL) {
                const pb = odPersonalBase();
                if (!pb) return null;
                folderPath = customCurrentFolderPath || (decodeParam(new URL(pb).pathname) + '/Documents');
            }

            // v11.11.0：OneDriveの通常画面で、フォルダの指定がないページ（ごみ箱・共有・onedrive.aspx など）→ 個人OneDriveの「ドキュメント」直下
            if (IS_MY_HOST && !folderPath) {
                const pb = odPersonalBase();
                if (pb) folderPath = decodeParam(new URL(pb).pathname) + '/Documents';
            }

            let needsLibResolve = false;
            if (!folderPath) {
                // v9.61：ライブラリ外のページ（サイトトップ等）。従来は常に別サイトの固定パスを
                // 使っていたため、他のサイトでは正しく動かなかった。現在のサイトの既定ライブラリを使う。
                const pageSite = getSiteUrlFromPathname(u.pathname, u.origin);
                if (pageSite !== u.origin) {
                    const siteRel = pageSite.slice(u.origin.length);
                    const cached = defaultLibCache.get(pageSite);
                    folderPath = cached || `${siteRel}/Shared Documents`;
                    needsLibResolve = !defaultLibCache.has(pageSite);
                } else {
                    folderPath = `/Shared Documents`;
                }
            }

            // サイトURLは「今表示しているページ」ではなく「実際にブラウズ対象にしているフォルダパス」から
            // 導出する。customCurrentFolderPath（左エリアからの同一画面移動・右エリアのフォルダ移動）で
            // 現在のページと別サイトコレクションのフォルダに移動した場合、現在ページのpathnameを使うと
            // 誤って現在のサイトへAPIを投げてしまい、0件表示になってしまうため。
            const siteUrl = getSiteUrlFromPathname(folderPath, u.origin);

            if (!listViewPathname) listViewPathname = guessAllItemsPath(folderPath);

            return {
                siteUrl,
                origin: /^\/personal\//i.test(folderPath) ? (odMyOrigin() || u.origin) : (IS_MY_HOST ? odSpOrigin() : u.origin),
                pathname: listViewPathname || u.pathname,
                listViewPathname,
                folderPath,
                viewId,
                needsLibResolve,
            };
        } catch (e) {
            return null;
        }
    }

    function extractFolderPathFromUrl(url) {
        try {
            const u = new URL(url, location.origin);
            // v11.10.0：個人OneDrive側（○○-my）のURLも同一画面移動の対象にする（別テナント等は従来どおり対象外）
            const isMyOrigin = !!odMyOrigin() && u.origin === odMyOrigin();
            if (u.origin !== location.origin && !isMyOrigin) return null;
            const hashQuery = u.hash.replace(/^#/, '');
            const hashParams = new URLSearchParams(hashQuery.startsWith('?') ? hashQuery.slice(1) : hashQuery);
            const idParam = decodeParam(u.searchParams.get('id') || u.searchParams.get('RootFolder')
                || hashParams.get('id') || hashParams.get('RootFolder'));
            if (idParam) return idParam;

            // v11.10.0：SharePoint内のOneDrive画面（マイファイル）→ 個人OneDriveの「ドキュメント」直下
            if (!isMyOrigin && /\/_layouts\/15\/sharepoint\.aspx\/onedrive(?:\/|$)/i.test(u.pathname)) {
                const pb = odPersonalBase();
                if (pb) { try { return decodeURIComponent(new URL(pb).pathname) + '/Documents'; } catch (e) { osxDbg('onedrive shell path', e); } }
                return null;
            }
            // OneDrive/SharePoint short share links: /:f:/r/sites/.../folder or /:f:/sites/.../folder
            const shareMatch = u.pathname.match(/^\/:f:(?:\/r)?(\/.+)$/i);
            if (shareMatch) {
                try { return decodeURIComponent(shareMatch[1]); } catch (e) { return shareMatch[1]; }
            }

            // v9.62：ドキュメントライブラリ自体のビューURL（…/<ライブラリ>/Forms/<ビュー>.aspx、idなし）
            // → ライブラリ直下のフォルダパスとして扱う。上位階層へ一切アクセスせずに済む。
            const libView = u.pathname.match(/^(\/(?:sites|teams|personal)\/[^/]+\/[^/]+)\/Forms\/[^/]+\.aspx$/i);
            if (libView) {
                try { return decodeURIComponent(libView[1]); } catch (e) { return libView[1]; }
            }

            if (!/\.aspx$/i.test(u.pathname)) {
                const parts = u.pathname.split('/').filter(Boolean);
                const third = (parts[2] || '').toLowerCase();
                if (parts.length >= 3 && (parts[0] === 'sites' || parts[0] === 'teams' || (isMyOrigin && parts[0] === 'personal')) && !SKIP_PATH_SEGMENTS.has(third)) {
                    return decodeURIComponent(u.pathname);
                }
            }
            // v11.10.0：個人OneDriveのトップ（…/personal/<ID>、またはフォルダ指定のない onedrive.aspx）→「ドキュメント」直下
            if (isMyOrigin) {
                const pm = u.pathname.match(/^\/personal\/([^/]+)(?:\/_layouts\/15\/onedrive\.aspx)?\/?$/i);
                if (pm) { try { return '/personal/' + decodeURIComponent(pm[1]) + '/Documents'; } catch (e) { return '/personal/' + pm[1] + '/Documents'; } }
            }
            return null;
        } catch (e) {
            return null;
        }
    }

    // v9.115：同一画面移動の対象フォルダを求める。
    //   従来は extractFolderPathFromUrl() が null を返す（サイトトップ／共有リンク等）と
    //   「同一画面移動できない」と判断して新規タブへ逃げていた。サイトが違うショートカットで
    //   新しいタブが開く原因。ここでは次の順で解決し、できる限り同一画面に留める。
    //   ①登録時に保存したサーバー相対パス → ②URLからの抽出 → ③サイトトップなら既定ライブラリ
    //   → ④共有リンク（/:f:/s/…）ならSharePointに問い合わせて実フォルダへ。
    function isFileLikeShortcut(app) {
        if (!app) return false;
        if (app.kind !== 'file') return false;
        // kind が file でも、URLがフォルダを指している（登録時に判定できなかっただけの）場合はフォルダ扱い。
        try {
            const u = new URL(app.url, location.origin);
            const id = decodeParam(u.searchParams.get('id') || u.searchParams.get('RootFolder'));
            if (id && looksLikeFilePath(id)) return true;
            if (looksLikeFilePath(u.pathname)) return true;
            if (/\/_layouts\/15\/(?:Doc|WopiFrame)\.aspx/i.test(u.pathname) || /\/:[a-z]:\//i.test(u.pathname) && !/\/:f:\//i.test(u.pathname)) return true;
        } catch (e) { return true; }
        return false;
    }

    function resolveInPlaceFolderPathSync(app) {
        if (!app) return null;
        const direct = app.rawServerRelativeUrl || app._serverRelativeUrl;
        if (direct && !looksLikeFilePath(direct)) return direct;
        let url = app.url;
        let p = extractFolderPathFromUrl(url);
        // 共有リンク（/:f:/s/サイト名/トークン）は実パスではないので、ここでは採用しない
        if (p && /^\/s\/[^/]+\/[^/]+$/.test(p) && /\/:f:\/s\//i.test(String(url))) p = null;
        return p || null;
    }

    function siteTopLibraryTarget(app) {
        try {
            const u = new URL(app.url, location.origin);
            if (u.origin !== location.origin) return null;
            const parts = u.pathname.split('/').filter(Boolean);
            if (parts.length < 2 || (parts[0] !== 'sites' && parts[0] !== 'teams')) return null;
            // /sites/X ・/sites/X/ ・/sites/X/SitePages/Home.aspx ・/sites/X/_layouts/… はサイトトップ扱い
            if (parts.length === 2 || /^(sitepages|_layouts|_catalogs|siteassets|lists)$/i.test(parts[2] || '')) {
                return `${u.origin}/${parts[0]}/${parts[1]}`;
            }
        } catch (e) { osxDbg('new URL', e); }
        return null;
    }

    async function resolveInPlaceFolderPathAsync(app) {
        const top = siteTopLibraryTarget(app);
        if (top) {
            const lib = await ensureDefaultLibrary(top);
            if (lib) return lib;
        }
        // 共有リンク → 実際のwebUrlへ（OneDrive/SharePoint共通の shares API）
        try {
            if (/\/:[a-z]:\//i.test(app.url)) {
                const b64 = btoa(unescape(encodeURIComponent(app.url))).replace(/=+$/, '').replace(/\//g, '_').replace(/\+/g, '-');
                const api = `${location.origin}/_api/v2.0/shares/u!${b64}/driveItem?$select=webUrl,folder`;
                const r = await fetch(api, { credentials: 'include', headers: { Accept: 'application/json' } });
                if (r.ok) {
                    const j = await r.json();
                    if (j && j.webUrl && (!j.folder || j.folder)) {
                        const wu = new URL(j.webUrl);
                        if (wu.origin === location.origin) {
                            const path = decodeURIComponent(wu.pathname);
                            if (path && !looksLikeFilePath(path)) return path;
                        }
                    }
                }
            }
        } catch (e) { osxDbg('i.test', e); }
        return null;
    }

    function goInPlaceFolder(folderPath) {
        customCurrentFolderPath = folderPath;
        refreshAutoFolders();
    }

    function tryNavigateInPlaceFolder(app) {
        if (!navigateInPlace) return false;
        if (!app || isFileLikeShortcut(app)) return false;
        const folderPath = resolveInPlaceFolderPathSync(app);
        if (folderPath) { goInPlaceFolder(folderPath); return true; }
        // 同期で解決できない（サイトトップ／共有リンク）場合も、まず同一画面で解決を試みる。
        // 別オリジン（別テナント等）のURLだけは同一画面では表示できないので従来どおり新規タブ。
        let sameOrigin = true;
        try { sameOrigin = new URL(app.url, location.origin).origin === location.origin; } catch (e) { osxDbg('new URL', e); }
        if (!sameOrigin) return false;
        resolveInPlaceFolderPathAsync(app).then((p) => {
            if (p) { goInPlaceFolder(p); return; }
            showToast('このショートカットは同一画面で開けないため、新しいタブで開きました');
            openWindow(app);
        }).catch(() => openWindow(app));
        return true;
    }

    // v11.43.11：ローカルパス（社内ファイルサーバー等）のショートカット対応。
    // \\サーバー\共有\... のようなWindowsパスが登録されていると、従来は内部の窓（iframe）に
    // そのまま入って何も表示されなかった。v11.43.11 では file:// で直接開く方式を試したが、
    // 実機ではブラウザ／社内ポリシーが https ページからの file:// 遷移を止めて無反応だった
    // （利用者の実機確認）。そのため v11.43.12 からは確実に届く方式にする：ダブルクリックで
    // パスを自動コピーし、画面下の案内（トースト）でエクスプローラーへ貼るよう伝える。
    function osxLocalParse(raw) {
        let u = String(raw || '').trim();
        if (!u) return null;
        u = u.replace(/^[¥￥]+/, (m) => '\\'.repeat(m.length));   // 先頭の円記号はバックスラッシュとして扱う
        const dec = (x) => { try { return decodeURIComponent(x); } catch (e) { return x; } };
        if (/^file:/i.test(u)) {
            const segs = u.replace(/^file:/i, '').replace(/\\/g, '/').replace(/^\/+/, '').split('/').filter(Boolean).map(dec);
            if (!segs.length) return null;
            if (/^[A-Za-z]:$/.test(segs[0])) return { fileUrl: 'file:///' + segs.map(encodeURIComponent).join('/'), winPath: segs.join('\\') };
            return { fileUrl: 'file://' + segs.map(encodeURIComponent).join('/'), winPath: '\\\\' + segs.join('\\') };
        }
        if (/^(\\\\|\/\/)/.test(u)) {   // UNC（\\server\share\... または //server/share/...）
            const segs = u.replace(/^[\\/]+/, '').split(/[\\/]+/).filter(Boolean);
            if (segs.length < 2) return null;
            return { fileUrl: 'file://' + segs.map(encodeURIComponent).join('/'), winPath: '\\\\' + segs.join('\\') };
        }
        const dm = /^([A-Za-z]):[\\/](.*)$/.exec(u);   // ドライブパス（C:\...）
        if (dm) {
            const segs = dm[2].split(/[\\/]+/).filter(Boolean);
            return { fileUrl: 'file:///' + dm[1] + ':' + (segs.length ? '/' + segs.map(encodeURIComponent).join('/') : ''), winPath: dm[1] + ':\\' + segs.join('\\') };
        }
        return null;
    }
    function osxOpenLocalPath(app) {
        const p = app && osxLocalParse(app.url);
        if (!p) return false;
        addToRecent(app);
        copyTextPlain(p.winPath).then((okCopy) => {
            showToast(okCopy
                ? 'ローカルのパスをコピーしました。エクスプローラーのアドレス欄に貼って移動してください'
                : 'コピーに失敗しました（ブラウザの権限をご確認ください）');
        }).catch((e) => { osxDbg('osxOpenLocalPath', e); showToast('コピーに失敗しました（ブラウザの権限をご確認ください）'); });
        return true;
    }

    function handleAppOpen(app) {
        bumpUsage(app);
        // v11.43.22：ZIPの中のアイテムは種類ごとの通常アクションで開く／ZIPファイル自体はフォルダのように開く
        if (app && app._zipEntry) { osxZipOpenEntry(app).catch((e) => { osxDbg('osxZipOpenEntry', e); showToast('開けませんでした：' + ((e && e.message) || String(e))); }); return; }
        if (app && typeof app._zipFolder === 'string') { if (osxZipView) { osxZipView.inner = app._zipFolder; osxZipRender(); } return; }
        if (app && /\.zip$/i.test(String(app.label || '')) && getServerRelativePathForFile(app)) { osxZipEnter(app).catch((e) => { osxDbg('osxZipEnter', e); showMessageModal('ZIPを開けませんでした', (e && e.message) || String(e)); }); return; }
        if (osxOpenLocalPath(app)) return;   // v11.43.12：ローカルパスは自動コピー＋案内
        if (tryNavigateInPlaceFolder(app)) return;
        openWindow(app);
    }

    // v11.17.0：タッチモード（[M7]）用の開き方。フォルダ＝同一画面で移動／ファイル＝ブラウザで開く（Office は Office for the web）／それ以外＝新しいタブ。
    //   戻り値：'folder'（右エリアが移る）／'file'（ブラウザで開いた）／'tab'（新しいタブで開いた）。デスクトップアプリは起動しない。
    function osxTouchIsFile(app) {
        if (!app) return false;
        if (app.kind === 'file') return isFileLikeShortcut(app);
        if (app.kind === 'folder') return false;
        try {
            const u = new URL(app.url, location.origin);
            const id = decodeParam(u.searchParams.get('id') || u.searchParams.get('RootFolder'));
            if (id && looksLikeFilePath(id)) return true;
            if (looksLikeFilePath(u.pathname)) return true;
        } catch (e) { osxDbg('osxTouchIsFile', e); }
        return false;
    }
    function osxTouchOpen(app, auto) {
        if (!app) return 'tab';
        bumpUsage(app);
        // v11.43.22：ZIPの中のアイテム／ZIPファイル（タッチモードでも同じ扱い）
        if (app._zipEntry) { osxZipOpenEntry(app).catch((e) => { osxDbg('osxZipOpenEntry', e); showToast('開けませんでした：' + ((e && e.message) || String(e))); }); return 'file'; }
        if (typeof app._zipFolder === 'string') { if (osxZipView) { osxZipView.inner = app._zipFolder; osxZipRender(); } return 'folder'; }
        if (/\.zip$/i.test(String(app.label || '')) && getServerRelativePathForFile(app)) { osxZipEnter(app).catch((e) => { osxDbg('osxZipEnter', e); showMessageModal('ZIPを開けませんでした', (e && e.message) || String(e)); }); return 'folder'; }
        if (osxOpenLocalPath(app)) return 'tab';   // v11.43.12：ローカルパスは自動コピー＋案内
        if (auto && app.kind === 'folder' && app._serverRelativeUrl) { goInPlaceFolder(app._serverRelativeUrl); return 'folder'; }
        if (auto && app.kind === 'file') {
            openFileInBrowser({ label: app.label, url: app.url, _serverRelativeUrl: app._serverRelativeUrl, rawServerRelativeUrl: app._serverRelativeUrl, origin: app.origin });
            return 'file';
        }
        if (osxTouchIsFile(app)) {
            addToRecent(app);
            const path = shortcutFileServerPath(app);   // 実ファイルのサーバー相対パス（分かる範囲）
            if (path) {
                openFileInBrowser({ label: app.label, url: app.url, _serverRelativeUrl: path, rawServerRelativeUrl: path, origin: app.origin });
                return 'file';
            }
            // 実ファイルの場所が分からない（共有リンクなど）：リンクをそのまま開く。Office には ?web=1 を付けてブラウザ版で開く
            let url = String(app.url || '');
            const ext = getFileExt({ label: app.label, url });
            if (OFFICE_WEB_EXTS.has(ext) && !/[?&]web=1(?:&|$)/.test(url)) url += (url.includes('?') ? '&' : '?') + 'web=1';
            window.open(url, '_blank');
            return 'file';
        }
        const wasInPlace = navigateInPlace;
        navigateInPlace = true;   // 設定に関わらず、フォルダは同一画面で移動する（この呼び出しの間だけ）
        let moved = false;
        try { moved = tryNavigateInPlaceFolder(app); } finally { navigateInPlace = wasInPlace; }
        if (moved) return 'folder';
        window.open(app.url, '_blank');
        return 'tab';
    }

    // v9.114：ファイル（画像・PDF・Office等）を開いているページかを判定する。
    // SharePointは画像などを開くと「AllItems.aspx?id=/…/ファイル.PNG&parent=/…/フォルダ」という
    // URLでプレビューを表示する。従来はこれを「フォルダ一覧のページ」と誤判定し、ファイルのパスを
    // フォルダとして扱ってUIが自動起動していた（通常画面に戻すと「このフォルダーは空です」になる）。
    const FILE_VIEW_EXTS = ['png','jpg','jpeg','gif','bmp','webp','svg','tif','tiff','heic','ico',
        'pdf','xlsx','xlsm','xlsb','xls','csv','docx','docm','doc','pptx','pptm','ppt','vsdx','one','msg','eml',
        'txt','log','json','xml','html','htm','md','zip','7z','rar','lzh','mp4','mov','avi','wmv','mp3','wav','m4a','dwg','dxf','stp','step'];
    function looksLikeFilePath(p) {
        const seg = String(p || '').split('?')[0].replace(/\/+$/, '').split('/').pop() || '';
        let name = seg;
        try { name = decodeURIComponent(seg); } catch (e) { osxDbg('decodeURIComponent', e); }
        const m = /\.([A-Za-z0-9]{1,5})$/.exec(name);
        return !!(m && FILE_VIEW_EXTS.includes(m[1].toLowerCase()));
    }
    function isFileViewPage() {
        try {
            const u = new URL(location.href);
            const hq = u.hash.replace(/^#/, '');
            const hp = new URLSearchParams(hq.startsWith('?') ? hq.slice(1) : hq);
            const id = u.searchParams.get('id') || u.searchParams.get('RootFolder') || hp.get('id') || hp.get('RootFolder');
            const parent = u.searchParams.get('parent') || hp.get('parent');
            if (id && (looksLikeFilePath(id) || (parent && /\.[A-Za-z0-9]{1,5}$/.test(String(id).split('/').pop() || '')))) return true;
            if (!/\.aspx$/i.test(u.pathname) && looksLikeFilePath(u.pathname)) return true;
        } catch (e) { osxDbg('new URL', e); }
        return false;
    }

    // v9.149.10：このページではUIを自動起動しない（ボタンだけ表示し、押したときだけ開く）。
    //   サイトの設定系ページ（記憶域メトリックス等）と、通常画面のごみ箱（RecycleBin.aspx）が対象。
    function isNoAutoLaunchPage() {
        // v11.43.96：個人OneDrive側でも自動起動する（v11.11.0の「ボタンを押したときだけ開く」を解除。設定系ページの除外は下の判定で従来どおり効く）
        const p = location.pathname;
        if (/\/_layouts\/15\/(storman|settings|viewlsts|user|people|mngsubwebs|prjsetng|(?:admin)?recyclebin)\.aspx$/i.test(p)) return true;
        return false;
    }

    function isTargetPage() {
        // v9.93.1：OneDriveは対象外にしていたが、v11.9.0で個人OneDriveの「ドキュメント」を表示する方式に対応したため対象にする
        if (IS_OD_SHELL) return true;
        // v9.114：ファイルを開いているページ（プレビュー含む）ではUIを出さない
        if (isFileViewPage()) return false;
        // v9.149.10：設定系ページ（記憶域メトリックス／ごみ箱など）でも「ショートカットUI」ボタンは表示する。
        //            （UIを自動で開かないだけ。判定は isNoAutoLaunchPage() を参照）
        const path = location.pathname.toLowerCase();
        const search = location.search.toLowerCase();
        if (path.includes('/_layouts/') || path.includes('/forms/')) {
            if (path.endsWith('/allitems.aspx')) return true;
            if (path.includes('doc.aspx') || path.includes('editform.aspx') || path.includes('dispform.aspx')) {
                return false;
            }
        }
        for (const ext of ['.xlsx', '.xls', '.docx', '.doc', '.pptx', '.pdf', '.msg']) {
            if (path.endsWith(ext) || search.includes(ext)) {
                return false;
            }
        }
        return true;
    }

