    document.body.appendChild(desktop);

    const miniToggle = document.createElement('button');
    miniToggle.id = 'os-mini-toggle';
    miniToggle.textContent = 'ショートカットUI';
    document.body.appendChild(miniToggle);

    desktop.style.display = 'none';

    function hideDesktop() {
        const ctx = getCurrentFolderContext();
        if (!IS_OD_SHELL && ctx && ctx.folderPath) {
            const targetUrl = buildBreadcrumbUrl(ctx, ctx.folderPath);
            // v9.87：通常画面へ戻る直後の読み込みでは自動起動しない（15秒以内の1回だけ有効）
            try { sessionStorage.setItem(SKIP_LAUNCH_KEY, String(Date.now())); } catch (e) { osxDbg('sessionStorage.setItem', e); }
            desktop.style.display = 'none';
            if (isTargetPage()) {
                miniToggle.style.setProperty('display', 'block', 'important');
            }
            location.href = targetUrl;
            return;
        }
        desktop.style.display = 'none';
        if (isTargetPage()) {
            miniToggle.style.setProperty('display', 'block', 'important');
        }
    }

    function showDesktop() {
        desktop.style.display = '';
        miniToggle.style.setProperty('display', 'none', 'important');
        refreshAutoFolders();
        renderCategoryZones();
        autoArrangeIfOn();
        updateTrashBadge();
    }
    miniToggle.addEventListener('click', showDesktop);

    const manualIconsLayer = desktop.querySelector('#os-icons-manual');
    const autoIconsLayer = desktop.querySelector('#os-icons-auto');
    const autoIconsWrapEl = desktop.querySelector('#os-icons-auto-wrap') || autoIconsLayer;
    const trashIconEl = desktop.querySelector('#os-trash-icon');
    const trashBadgeEl = desktop.querySelector('#os-trash-badge');
