    const THEME_KEY = 'osDesktopTheme_v1';
    // v9.111.0：「最強にかわいい」テーマ用の壁紙タイル（ハート・星・キラキラ）。SVGをその場で作って背景にするだけ（外部通信なし）
    function kawaiiTile(heart, star, dot) {
        const H = 'M10 4.5C10 .5 3 .5 3 6c0 4.5 7 9.5 7 9.5s7-5 7-9.5C17 .5 10 .5 10 4.5z';
        const S = 'M0-10C1-3 3-1 10 0C3 1 1 3 0 10C-1 3-3 1-10 0C-3-1-1-3 0-10z';
        const svg = '<svg xmlns="http://www.w3.org/2000/svg" width="160" height="160" viewBox="0 0 160 160">'
            + '<g fill="' + heart + '">'
            + '<path d="' + H + '" transform="translate(16 14) scale(1.5)"/>'
            + '<path d="' + H + '" transform="translate(104 88) scale(1.1)"/>'
            + '<path d="' + H + '" transform="translate(58 124) scale(0.8)"/>'
            + '<path d="' + H + '" transform="translate(126 22) scale(0.7)"/>'
            + '</g><g fill="' + star + '">'
            + '<path d="' + S + '" transform="translate(84 38) scale(1.2)"/>'
            + '<path d="' + S + '" transform="translate(30 92) scale(0.8)"/>'
            + '<path d="' + S + '" transform="translate(142 136) scale(1)"/>'
            + '<path d="' + S + '" transform="translate(64 8) scale(0.55)"/>'
            + '</g><g fill="' + dot + '">'
            + '<circle cx="48" cy="62" r="3"/><circle cx="116" cy="54" r="2.4"/><circle cx="12" cy="140" r="2.6"/><circle cx="92" cy="146" r="2"/><circle cx="150" cy="84" r="2.4"/>'
            + '</g></svg>';
        return 'url("data:image/svg+xml,' + encodeURIComponent(svg) + '") 0 0 / 160px 160px';
    }
