            lay(g3Skyline(W, 330, 'g3c1', '#3a1466', '#8a5ad0', '#c890ff', 0.5), 330, G3_GROUND, 140);
            lay(g3Skyline(W, 250, 'g3c2', '#1e0a40', '#ff6ad0', '#6af0ff', 0.55), 250, G3_GROUND, 80);
            lay(g3Skyline(W, 160, 'g3c3', '#0c0420', '#ffd860', '#ff6ad0', 0.5), 160, G3_GROUND, 38);
            [['ホテル', '#ff3da8', 18, 38], ['ＢＡＲ', '#3df0ff', 62, 52], ['24H', '#ffe03d', 84, 30]].forEach((n, i) => add('g3a g3ng', n[0], 'left:' + n[2] + '%;top:' + n[3] + '%;color:' + n[1] + ';--dl:-' + f1(i * 0.6) + 's'));
            if (hi) for (let i = 0; i < 40; i++) add('g3a g3rn', '', 'left:' + f1(R(0, 100)) + '%;--d:' + f1(R(.5, 1)) + 's;--dl:-' + f1(R(0, 1)) + 's;height:' + f1(R(16, 40)) + 'px');
