                + 'color:' + (note ? '#1f2937' : color) + ';background:' + (note ? osxMemoPastel(color) : 'rgba(255,255,255,.9)') + ';font-size:' + fs + 'px;left:' + (x * v.z + v.ox) + 'px;top:' + (y * v.z + v.oy) + 'px;';
