            ui.numInfo = document.createElement('span'); ui.numInfo.className = 'osxm-grp'; ui.numInfo.appendChild(document.createTextNode(''));
            const numReset = document.createElement('button'); numReset.type = 'button'; numReset.className = 'osxm-b'; numReset.textContent = '↺ 1から'; numReset.title = '番号を1に戻す';
            numReset.addEventListener('click', () => { page().seq = 1; osxMemoScheduleSave(); updateUi(); });
            ui.numInfo.appendChild(numReset); bar1.appendChild(ui.numInfo);
            mkSep(bar1);
            ui.undoBtn = mkBtn(bar1, '↩', '戻す（Ctrl+Z）', undo);
            ui.redoBtn = mkBtn(bar1, '↪', 'やり直し（Ctrl+Y）', redo);
            ui.delBtn = mkBtn(bar1, '🗑 削除', '選択中の物を削除（Delete）', deleteSel);
            const clearBtn = mkBtn(bar1, '全消し', 'このページの内容を全部消す（↩で戻せます）', () => {
                if (clearBtn.dataset.arm) { delete clearBtn.dataset.arm; clearBtn.textContent = '全消し'; commit((p) => { p.ops = []; p.seq = 1; }); sel.clear(); showToast('消しました（↩ で戻せます）'); }
                else { clearBtn.dataset.arm = '1'; clearBtn.textContent = '本当に消す？'; clearTimeout(clearArmTimer); clearArmTimer = setTimeout(() => { delete clearBtn.dataset.arm; clearBtn.textContent = '全消し'; }, 2600); }
            });
            mkSep(bar1);
            mkBtn(bar1, '🖼 貼付', 'クリップボードの画像を貼る（メモの上で Ctrl+V でも可）', pasteFromClipboardBtn);
            mkBtn(bar1, '📸 キャプチャ', '画面・ウィンドウを撮って貼る（Excelや業務画面の不良箇所に描き込めます）', captureScreen);
            mkBtn(bar1, '？', '使い方のコツ', toggleHelp);

            // 行2：オプション（今のツールに関係あるものだけ表示）
            const bar2 = mkBar();
            ui.gColor = mkGrp(bar2); ui.sw = [];
            OSXM_PALETTE.forEach(([c, nm]) => {
                const b = document.createElement('button'); b.type = 'button'; b.className = 'osxm-sw'; b.title = nm; b.setAttribute('aria-label', nm); b.style.background = c;
                b.addEventListener('click', () => { st.color = c; applyToSel(() => ({ color: c }), ['s', 'l', 'r', 'e', 'x', 'n']); updateUi(); });
                ui.gColor.appendChild(b); ui.sw.push({ el: b, c });
            });
            ui.custom = document.createElement('input'); ui.custom.type = 'color'; ui.custom.title = '好きな色'; ui.custom.style.cssText = 'width:30px;height:26px;padding:0;border:1px solid #94a3b8;border-radius:5px;background:#fff;cursor:pointer;';
            ui.custom.addEventListener('input', () => { st.color = ui.custom.value; applyToSel(() => ({ color: ui.custom.value }), ['s', 'l', 'r', 'e', 'x', 'n']); updateUi(); });
