        fontSec.append(fontCustCap, fontCustRow, fontCustMsg, fontNote);

        // v1.1.0：🧩 機能の切替（ライトモード）。初期設定はすべてオフ
        const featSec = document.createElement('div');
        featSec.style.cssText = 'margin:6px 0 8px;padding:8px 10px;border:1px solid #bbf7d0;border-left:4px solid #16a34a;border-radius:8px;background:#f0fdf4;';
