                            const ul = [...um.values()].sort((a, b2) => b2.size - a.size).slice(0, 5);
                            det.appendChild(mkLine((basis === 'Created' ? '作った人' : '更新した人') + '：' + ul.map((g) => g.name + ' ' + hvFmtSize(g.size) + '（' + g.n + '件）').join('　'), 'font-size:11px;color:#475569;margin:2px 0 4px;'));
                            const top = b.files.slice().sort((x, y) => y.size - x.size).slice(0, 10);
