            const rpTa = document.createElement('textarea');
            rpTa.readOnly = true; rpTa.style.cssText = 'display:none;width:100%;box-sizing:border-box;height:260px;font:12px/1.5 monospace;margin:6px 0;padding:6px;';
            const rpOut = mkList();
            rpBox.append(mkMemo('ボタン1つで、移行日以降の状況をまとめて調べます（数分かかります。版の履歴を1ファイルずつ読むため、ファイル数が多いほど時間がかかります）。「版を含めた増加量」は、移行日以降に保存された版の容量＋現行ファイルの容量から推定します。上限件数までの調査（大きいファイル優先）なので、小さいファイルの分は含まれません。読み取りだけで、SharePointには何も書き込みません。'), rpCtl, rpTa, rpOut);

            let rpFilesCsv = null;
