                rpFilesCsv.forEach((r, i) => rows.push([i + 1, r.name, r.size, r.saves, r.add, r.vs.length, r.pastSum, r.editor, capCsvDate(r.mod), parentOf(r.path), r.path]));
                capCsvDownload('容量_報告用_ファイル別', rows);
