    const OPLOG_KEY = 'osDesktopOpLog_v1';
    const OPLOG_SEEN_KEY = 'osDesktopSeenVersion_v1';
    const OPLOG_MAX = 500;

    function opLogRead() {
        return osxLs.getArray(OPLOG_KEY);
    }
    function opLogWrite(arr) {
        let n = OPLOG_MAX;
        while (n >= 50) {
            if (osxLs.setJson(OPLOG_KEY, arr.slice(0, n))) return;
            n = Math.floor(n / 2);
        }
    }
    // e: { action, name, path, dest, ok(false=失敗), msg }
    function opLogAdd(e) {
        try {
            const arr = opLogRead();
            arr.unshift({
                t: Date.now(), a: String(e.action || ''), n: String(e.name || ''), p: String(e.path || ''), d: String(e.dest || ''),
                r: e.ok === false ? 'ng' : 'ok', m: String(e.msg || '').slice(0, 200),
            });
            opLogWrite(arr);
        } catch (er) { osxDbg('opLogRead', er); }
        try { const w = document.getElementById('os-oplog-overlay'); if (w && w._refresh) w._refresh(); } catch (er) { osxDbg('document.getElementById', er); }
    }
    function opLogFmtTime(t) {
        const d = new Date(t);
        const p = (n) => String(n).padStart(2, '0');
        return `${d.getFullYear()}/${p(d.getMonth() + 1)}/${p(d.getDate())} ${p(d.getHours())}:${p(d.getMinutes())}:${p(d.getSeconds())}`;
    }
    function opLogUserName() {
        try { return (osxPageWin._spPageContextInfo && osxPageWin._spPageContextInfo.userDisplayName) || ''; } catch (e) { return ''; }
    }

    // ===== v11.20.0：操作ログから「元に戻す」 =====
    // 対象は、このUIで行った 名前変更／移動／移動（ドラッグ）／コピー／削除（ごみ箱へ） の成功記録だけ。
    // ログの記録（n＝名前、p＝場所、d＝移動先・コピー先、m＝メモ）から逆操作を組み立て、実行前に
    // 「今もその場所にあるか」「戻し先に同名が無いか」を確認してから、[S10] と同じREST手順で戻す。
    // 取り消しの実行も同じ形式でログに残る（移動の取り消しは逆方向の「移動」として記録されるので、
    // その記録をさらに取り消せば「やり直し」になる）。元の記録には u（取り消した時刻）を付けて二重実行を防ぐ。
    function opLogUndoPlan(x) {
        if (!x || x.r === 'ng' || x.u) return null;
        if (x.a === '名前変更') {
            const i = String(x.n || '').indexOf(' → ');
            if (i < 1 || !x.p) return null;
            return { kind: 'rename', parent: x.p, oldName: String(x.n).slice(0, i), newName: String(x.n).slice(i + 3) };
        }
        if (x.a === '移動' || x.a === '移動（ドラッグ）') {
            if (!x.p || !x.d || !x.n) return null;
            return { kind: 'move', name: x.n, from: x.d, to: x.p };
        }
        if (x.a === 'コピー') {
            if (!x.d || !x.n) return null;
            const mm = /^新しい名前：(.+)$/.exec(String(x.m || ''));
            return { kind: 'copy', name: mm ? mm[1] : x.n, folder: x.d };
        }
        if (x.a === '削除（ごみ箱へ）') {
            if (!x.p || !x.n) return null;
            return { kind: 'restore', name: x.n, dir: x.p };
        }
        return null;
    }
    function opLogMarkUndone(x) {
        try {
            const arr = opLogRead();
            const hit = arr.find((e) => e.t === x.t && e.a === x.a && e.n === x.n && e.p === x.p && e.d === x.d);
            if (hit) { hit.u = Date.now(); opLogWrite(arr); }
        } catch (e) { osxDbg('opLogMarkUndone', e); }
    }
    function spEndpointForPath(siteUrl, path, isFolder) {
        const q = apiQuotedPath(path);
        return `${siteUrl}/_api/web/${isFolder ? spFolderFn(path) : spFileFn(path)}?@p=${q}`;
    }
    async function spProbeKind(siteUrl, path) {
        // ファイル→フォルダの順に Exists を見る（404エラーは「無い」として扱う。[S10] spMoveOrCopyOne の existsAt と同じ）
        for (const isFolder of [false, true]) {
            const ep = `/_api/web/${isFolder ? spFolderFn(path) : spFileFn(path)}/Exists?@p=${apiQuotedPath(path)}`;
            try {
                const r = await spRestRequest(siteUrl, ep, { method: 'GET' });
                const v = r && r.d ? (r.d.Exists !== undefined ? r.d.Exists : r.d) : r;
                if (v === true || v === 'true') return isFolder ? 'folder' : 'file';
            } catch (e) { /* 無いものとして次へ */ }
        }
        return null;
    }
    async function spRenameAtPath(siteUrl, path, isFolder, newName) {
        // sharePointRename と同じ手順（ListItemAllFields の FileLeafRef を MERGE）
        const itemApiPath = spEndpointForPath(siteUrl, path, isFolder).replace(siteUrl, '').replace('?', '/ListItemAllFields?');
        const info = await spRestRequest(siteUrl, itemApiPath, { method: 'GET' });
        const entityType = (info && info.d && info.d.__metadata && info.d.__metadata.type) || 'SP.ListItem';
        await spRestRequest(siteUrl, itemApiPath, {
            method: 'POST',
            headers: { 'IF-MATCH': '*', 'X-HTTP-Method': 'MERGE' },
            body: { __metadata: { type: entityType }, FileLeafRef: newName },
        });
    }
    async function spMoveAtPath(siteUrl, path, isFolder, newPath) {
        const call = isFolder ? '/MoveTo(newUrl=@n)' : '/MoveTo(newUrl=@n,flags=0)';
        const apiPath = spEndpointForPath(siteUrl, path, isFolder).replace(siteUrl, '').replace('?', call + '?') + '&@n=' + apiQuotedPath(newPath);
        await spRestRequest(siteUrl, apiPath, { method: 'POST' });
    }
    async function spRecycleAtPath(siteUrl, path, isFolder) {
        const rec = spEndpointForPath(siteUrl, path, isFolder).replace(/\?/, '/recycle()?');
        await spRestRequest(siteUrl, rec.replace(siteUrl, ''), { method: 'POST' });
    }
    // v11.20.1：元に戻す専用の確認ダイアログ。showDangerConfirmModal は削除専用（ボタンが「削除する」固定で
    // 3秒カウントダウンもある）ため流用せず、showMoveConfirmModal と同じ作法（通常ヘッダー／実行ボタンは
    // 操作に合った文言／既定フォーカスはキャンセル／Esc・✕は中止）で新設した。
    function showUndoConfirmModal(title, message, targetLabel, okLabel) {
        return new Promise((resolve) => {
            let settled = false;
            const overlay = document.createElement('div');
            overlay.className = 'osx3-overlay';
            const panel = document.createElement('div');
            panel.className = 'osx3-panel';
            const header = document.createElement('div');
            header.className = 'osx3-header';
            const titleEl = document.createElement('span');
            titleEl.className = 'osx3-title';
            titleEl.textContent = `↩ ${title}`;
            const closeBtn = document.createElement('button');
            closeBtn.className = 'osx3-close';
            closeBtn.textContent = '✕';
            header.append(titleEl, closeBtn);
            const body = document.createElement('div');
            body.className = 'osx3-body';
            const msgLine = document.createElement('div');
            msgLine.textContent = message;
            body.appendChild(msgLine);
            if (targetLabel) {
                const targetLine = document.createElement('div');
                targetLine.style.marginTop = '6px';
                targetLine.style.fontWeight = 'bold';
                targetLine.textContent = `対象：${targetLabel}`;
                body.appendChild(targetLine);
            }
            const actions = document.createElement('div');
            actions.className = 'osx3-actions';
            actions.style.justifyContent = 'flex-end';
            const cancelBtn = document.createElement('button');
            cancelBtn.className = 'osx3-button';
            cancelBtn.textContent = 'キャンセル';
            const okBtn = document.createElement('button');
            okBtn.className = 'osx3-button osx3-button-primary';
            okBtn.textContent = okLabel;
            function finish(v) {
                if (settled) return;
                settled = true;
                overlay.remove();
                resolve(v);
            }
            closeBtn.addEventListener('click', () => finish(false));
            cancelBtn.addEventListener('click', () => finish(false));
            okBtn.addEventListener('click', () => finish(true));
            document.addEventListener('keydown', function onKey(e) {
                if (settled) { document.removeEventListener('keydown', onKey); return; }
                if (e.key === 'Escape') { e.preventDefault(); finish(false); document.removeEventListener('keydown', onKey); }
            });
            actions.append(cancelBtn, okBtn);
            body.appendChild(actions);
            panel.append(header, body);
            overlay.appendChild(panel);
            document.body.appendChild(overlay);
            // Enter連打での誤実行を避けるため、既定フォーカスはキャンセル側（showMoveConfirmModal と同じ）
            setTimeout(() => cancelBtn.focus(), 0);
        });
    }
    async function opLogUndo(x) {
        const plan = opLogUndoPlan(x);
        if (!plan) return;
        const basePath = plan.kind === 'rename' ? plan.parent : (plan.kind === 'move' ? plan.from : (plan.kind === 'copy' ? plan.folder : plan.dir));
        const siteUrl = getSiteUrlFromPathname(basePath, location.origin);
        try {
            if (plan.kind === 'rename') {
                const curPath = plan.parent + '/' + plan.newName;
                const kind = await spProbeKind(siteUrl, curPath);
                if (!kind) throw new Error(`「${plan.newName}」が今の場所（${plan.parent}）に見つかりません。すでに移動・名前変更・削除された可能性があります。`);
                if (await spProbeKind(siteUrl, plan.parent + '/' + plan.oldName)) throw new Error(`戻し先に「${plan.oldName}」がすでにあります。同名があるため元に戻せません。`);
                const ok = await showUndoConfirmModal('名前変更を元に戻す', `「${plan.newName}」を元の名前「${plan.oldName}」に戻します（場所：${plan.parent}）。`, plan.newName, '元の名前に戻す');
                if (!ok) return;
                await spRenameAtPath(siteUrl, curPath, kind === 'folder', plan.oldName);
                opLogAdd({ action: '名前変更', name: plan.newName + ' → ' + plan.oldName, path: plan.parent });
            } else if (plan.kind === 'move') {
                const curPath = plan.from + '/' + plan.name;
                const kind = await spProbeKind(siteUrl, curPath);
                if (!kind) throw new Error(`「${plan.name}」が移動先（${plan.from}）に見つかりません。すでに移動・削除された可能性があります。`);
                if ((await spProbeKind(siteUrl, plan.to)) !== 'folder') throw new Error(`戻し先のフォルダ（${plan.to}）が見つかりません。`);
                if (await spProbeKind(siteUrl, plan.to + '/' + plan.name)) throw new Error(`戻し先に同名の「${plan.name}」がすでにあります。同名があるため元に戻せません。`);
                const ok = await showUndoConfirmModal('移動を元に戻す', `「${plan.name}」を ${plan.from} から元の場所 ${plan.to} へ移動します。`, plan.name, '元の場所へ移動する');
                if (!ok) return;
                await spMoveAtPath(siteUrl, curPath, kind === 'folder', plan.to + '/' + plan.name);
                opLogAdd({ action: x.a, name: plan.name, path: plan.from, dest: plan.to });
                try { if (osxMoveChannel) osxMoveChannel.postMessage({ type: 'moved', from: OSX_WIN_ID }); } catch (e) { osxDbg('osxMoveChannel.postMessage', e); }
            } else if (plan.kind === 'copy') {
                const curPath = plan.folder + '/' + plan.name;
                const kind = await spProbeKind(siteUrl, curPath);
                if (!kind) throw new Error(`コピーした「${plan.name}」（${plan.folder}）が見つかりません。すでに移動・削除された可能性があります。`);
                const ok = await showUndoConfirmModal('コピーを元に戻す', `コピーで作られた「${plan.name}」をSharePointのごみ箱へ移動します（ごみ箱からは元に戻せます）。元のファイルには影響しません。`, plan.name, 'ごみ箱へ移動する');
                if (!ok) return;
                await spRecycleAtPath(siteUrl, curPath, kind === 'folder');
                opLogAdd({ action: '削除（ごみ箱へ）', name: plan.name, path: plan.folder });
            } else if (plan.kind === 'restore') {
                const items = await rbFetchAll(siteUrl);
                const dirKey = String(plan.dir || '').replace(/^\/+/, '');
                const cands = (items || []).filter((it) => rbItemName(it) === plan.name && rbDirOf(it) === dirKey);
                if (!cands.length) throw new Error(`ごみ箱に「${plan.name}」（元の場所：${plan.dir}）が見つかりません。すでに復元・消去されたか、別のサイトのごみ箱の可能性があります。「🗑️ ごみ箱」窓からも確認できます。`);
                let pick = cands[0];
                if (cands.length > 1) {
                    const near = cands.map((it) => ({ it, diff: Math.abs((Date.parse(it.DeletedDate || '') || 0) - x.t) })).sort((a, b) => a.diff - b.diff)[0];
                    if (!near || near.diff > 10 * 60 * 1000) throw new Error(`ごみ箱に同名の「${plan.name}」が${cands.length}件あり、この記録のものか特定できませんでした。「🗑️ ごみ箱」窓から削除日時に近いものを選んでください。`);
                    pick = near.it;
                }
                const ok = await showUndoConfirmModal('削除を元に戻す', `ごみ箱にある「${plan.name}」を元の場所（${plan.dir}）へ戻します。`, plan.name, '元の場所へ戻す');
                if (!ok) return;
                await rbRestoreOne(siteUrl, pick);   // 復元の記録は rbRestoreOne がログに残す
            }
            opLogMarkUndone(x);
            try { await refreshAutoFolders(); } catch (e) { osxDbg('refreshAutoFolders', e); }
            showToast('元に戻しました');
        } catch (e) {
            await showMessageModal('元に戻せませんでした', (e && e.message) || String(e));
        }
    }

    function openOpLogWindow() {
        const old = document.getElementById('os-oplog-overlay');
        if (old) { osxWinCloseOrRestore(old); return; }
        let body = null;
        const overlay = createPanel('📜 操作ログ（このUIでの操作記録）', (b) => { body = b; }, {});
        overlay.id = 'os-oplog-overlay';
        const panel = overlay.querySelector('.osx3-panel');
        if (panel) panel.style.width = 'min(920px, 96vw)';

        const who = opLogUserName();
        const note = document.createElement('div');
        note.className = 'osxh-note';
        note.style.marginBottom = '6px';
        note.textContent = (who ? `${who} さんのこのブラウザの記録です。` : 'このブラウザの記録です。')
            + 'このUIから行った操作（ダウンロード／アップロード・新規作成／名前変更／移動／コピー／削除／テキスト保存／ごみ箱から復元）が、最大500件まで残ります。'
            + 'SharePointの通常画面での操作や、他の人・他のPCの操作は含まれません。'
            + '名前変更・移動・コピー・削除の記録には「↩ 元に戻す」が付き、その場で取り消せます（取り消しの実行も記録に残ります）。';
        const ctl = document.createElement('div');
        ctl.style.cssText = 'display:flex;gap:6px;flex-wrap:wrap;align-items:center;margin:4px 0 8px;font-size:12px;';
        const selA = document.createElement('select');
        const selR = document.createElement('select');
        [['', 'すべての結果'], ['ok', '成功だけ'], ['ng', '失敗だけ']].forEach(([v, t]) => { const o = document.createElement('option'); o.value = v; o.textContent = t; selR.appendChild(o); });
        const q = document.createElement('input');
        q.type = 'text';
        q.placeholder = 'ファイル名・場所で絞り込み';
        q.style.cssText = 'padding:4px 7px;border:1px solid #cbd5e1;border-radius:5px;min-width:200px;';
        const cnt = document.createElement('span');
        cnt.style.color = '#64748b';
        const mkBtn = (text, fn) => {
            const bt = document.createElement('button');
            bt.className = 'osx3-button';
            bt.style.cssText = 'padding:3px 9px;font-size:12px;';
            bt.textContent = text;
            bt.addEventListener('click', fn);
            return bt;
        };
        const list = document.createElement('div');
        list.style.cssText = 'border:1px solid #e2e8f0;border-radius:6px;max-height:60vh;overflow:auto;font-size:12px;';

        let shown = [];
        const render = () => {
            const all = opLogRead();
            const keep = selA.value;
            const actions = Array.from(new Set(all.map((x) => x.a))).sort();
            selA.replaceChildren();
            const o0 = document.createElement('option');
            o0.value = ''; o0.textContent = 'すべての操作';
            selA.appendChild(o0);
            actions.forEach((a) => { const o = document.createElement('option'); o.value = a; o.textContent = a; selA.appendChild(o); });
            selA.value = actions.includes(keep) ? keep : '';
            const key = String(q.value || '').trim().toLowerCase();
            shown = all.filter((x) => (!selA.value || x.a === selA.value) && (!selR.value || x.r === selR.value)
                && (!key || (x.n + ' ' + x.p + ' ' + x.d).toLowerCase().includes(key)));
            cnt.textContent = `${shown.length} 件を表示（全${all.length}件）`;
            list.replaceChildren();
            if (!shown.length) {
                const em = document.createElement('div');
                em.style.cssText = 'padding:22px;text-align:center;color:#64748b;';
                em.textContent = all.length ? '条件に合う記録がありません。' : 'まだ記録がありません。このUIでファイルの操作をすると、ここに残ります。';
                list.appendChild(em);
                return;
            }
            shown.slice(0, 300).forEach((x) => {
                const row = document.createElement('div');
                row.style.cssText = 'display:grid;grid-template-columns:128px 120px 1fr;gap:2px 10px;padding:5px 8px;border-bottom:1px solid #f1f5f9;' + (x.r === 'ng' ? 'background:#fef2f2;' : '');
                const c1 = document.createElement('div'); c1.style.color = '#475569'; c1.textContent = opLogFmtTime(x.t);
                const c2 = document.createElement('div'); c2.style.fontWeight = 'bold'; c2.textContent = (x.r === 'ng' ? '⚠ ' : '') + x.a;
                const c3 = document.createElement('div'); c3.style.cssText = 'word-break:break-all;';
                const nm = document.createElement('div'); nm.textContent = x.n;
                c3.appendChild(nm);
                const loc = [x.p ? '📂 ' + x.p : '', x.d ? '→ ' + x.d : ''].filter(Boolean).join('　');
                if (loc) { const l = document.createElement('div'); l.style.cssText = 'color:#64748b;font-size:11px;'; l.textContent = loc; c3.appendChild(l); }
                if (x.r === 'ng') { const m = document.createElement('div'); m.style.cssText = 'color:#b91c1c;font-size:11px;'; m.textContent = '失敗：' + (x.m || ''); c3.appendChild(m); }
                if (x.u) {
                    const u = document.createElement('div');
                    u.style.cssText = 'color:#94a3b8;font-size:11px;margin-top:2px;';
                    u.textContent = `↩ 元に戻し済み（${opLogFmtTime(x.u)}）`;
                    c3.appendChild(u);
                } else if (opLogUndoPlan(x)) {
                    const ub = document.createElement('button');
                    ub.className = 'osx3-button';
                    ub.style.cssText = 'padding:2px 9px;font-size:11px;margin-top:3px;';
                    ub.textContent = '↩ 元に戻す';
                    ub.title = 'この操作を取り消します（実行前に今の状態を確認し、確認画面を出します）';
                    ub.addEventListener('click', async () => {
                        ub.disabled = true; ub.textContent = '確認中…';
                        await opLogUndo(x);
                        render();
                    });
                    c3.appendChild(ub);
                }
                row.append(c1, c2, c3);
                list.appendChild(row);
            });
            if (shown.length > 300) {
                const more = document.createElement('div');
                more.style.cssText = 'padding:8px;text-align:center;color:#64748b;';
                more.textContent = `新しい300件を表示中です。残りは「Excel用にコピー」で全件を取り出せます。`;
                list.appendChild(more);
            }
        };
        overlay._refresh = render;
        selA.addEventListener('change', render);
        selR.addEventListener('change', render);
        q.addEventListener('input', render);
        const copyBtn = mkBtn('📋 Excel用にコピー（表示中の全件）', async () => {
            const head = ['日時', '操作', '対象', '場所', '移動先・コピー先', '結果', 'メモ'].join('\t');
            const cell = (s) => { s = String(s == null ? '' : s); return /[\t\n\r"]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s; };
            const text = head + '\n' + shown.map((x) => [opLogFmtTime(x.t), x.a, x.n, x.p, x.d, x.r === 'ng' ? '失敗' : '成功', x.m].map(cell).join('\t')).join('\n');
            showToast((await copyTextPlain(text)) ? `${shown.length} 件をExcel用にコピーしました` : 'コピーに失敗しました');
        });
        const clearBtn = mkBtn('🗑 ログを消去', async () => {
            const ok = await showDangerConfirmModal('操作ログを消去', 'このブラウザに残っている操作ログをすべて消します（SharePoint上のファイルには影響しません）。元に戻せません。', `${opLogRead().length}件のログ`);
            if (!ok) return;
            osxLs.remove(OPLOG_KEY);
            render();
            showToast('操作ログを消去しました');
        });
        ctl.append(selA, selR, q, cnt, copyBtn, clearBtn);
        body.append(note, ctl, list);
        render();
    }

    // ---- UIのバージョン履歴 ----
    function openChangelogWindow() {
        const old = document.getElementById('os-changelog-overlay');
        if (old) { osxWinCloseOrRestore(old); return; }
        let body = null;
        const overlay = createPanel('🆕 このUIの更新履歴', (b) => { body = b; }, {});
        overlay.id = 'os-changelog-overlay';
        const panel = overlay.querySelector('.osx3-panel');
        if (panel) panel.style.width = 'min(820px, 96vw)';
        const head = document.createElement('div');
        head.style.cssText = 'font-size:14px;font-weight:bold;margin-bottom:4px;';
        head.textContent = '現在のバージョン：v' + OSX_UI_VERSION;
        const note = document.createElement('div');
        note.className = 'osxh-note';
        note.style.marginBottom = '8px';
        note.textContent = '新しい順です。クリックで内容を開閉します。これより古い履歴は、スクリプト先頭のコメントにあります。';
        body.append(head, note);
        const wrap = document.createElement('div');
        wrap.style.cssText = 'max-height:62vh;overflow:auto;border:1px solid #e2e8f0;border-radius:6px;';
        OSX_CHANGELOG.forEach((c, i) => {
            const d = document.createElement('details');
            d.style.cssText = 'padding:4px 10px;border-bottom:1px solid #f1f5f9;';
            if (i < 2) d.open = true;
            const sm = document.createElement('summary');
            sm.style.cssText = 'cursor:pointer;font-size:13px;';
            const first = (c.t.split('\n')[0] || '').replace(/^[①-⑩]\s*/, '');
            sm.textContent = `v${c.v}　${first.length > 60 ? first.slice(0, 60) + '…' : first}`;
            if (i === 0) sm.style.fontWeight = 'bold';
            const pre = document.createElement('div');
            pre.style.cssText = 'white-space:pre-wrap;word-break:break-word;font-size:12.5px;line-height:1.6;color:#334155;padding:4px 0 6px;';
            pre.textContent = c.t;
            d.append(sm, pre);
            wrap.appendChild(d);
        });
        body.appendChild(wrap);
    }

    // バージョンが変わった最初の起動だけ、時計のヒントを出す
    setTimeout(() => {
        try {
            if (osxLs.get(OPLOG_SEEN_KEY) === OSX_UI_VERSION) return;
            if (!osxLs.set(OPLOG_SEEN_KEY, OSX_UI_VERSION)) return;   // 保存できない環境では毎回出さない
            showToast(`UIがv${OSX_UI_VERSION}に更新されました（右下の時計をクリックすると更新内容を見られます）`, '更新内容を見る', () => { if (!document.getElementById('os-changelog-overlay')) openChangelogWindow(); });
        } catch (e) { osxDbg('osxLs.get', e); }
    }, 2500);

    // v11.15.0：全設定バックアップのお知らせ（バージョン更新のお知らせと重ならないよう、少し遅らせて確認）
    setTimeout(() => {
        try {
            const days = osxSetRemindDue(Date.now());
            if (days == null) return;
            if (!osxLs.set(OSX_SET_REMIND_KEY, String(Date.now()))) return;   // 保存できない環境では毎回出さない
            const lm = osxSetLastBackupMs();
            showToast(lm ? `設定のバックアップを最後に取ってから${days}日たちました（ブラウザのデータ消去に備えて保存しておくと安心です）` : `設定のバックアップをまだ取っていません（ブラウザのデータ消去やPC入れ替えに備えて保存しておくと安心です）`, 'バックアップする', () => { if (!document.getElementById('os-io-modal')) osxSetOpenExport(); });
        } catch (e) { osxDbg('set.remind', e); }
    }, 10000);

    // v11.36.0：1stパックの案内（まったくの初回起動だけ。既存利用者には出さず、済み印だけ付ける）
    setTimeout(() => {
        try {
            if (osxLs.get(OSX_FIRSTPACK_KEY, '')) return;
            if (customApps.length > 0) { osxLs.set(OSX_FIRSTPACK_KEY, 'skip'); return; }
            osxFirstPackPrompt();
        } catch (e) { osxDbg('firstpack.boot', e); }
    }, 6000);

    // ---- 起動時の仕掛け ----
    async function fetchJson(url) {
        const res = await fetch(url, {
            headers: { Accept: 'application/json;odata=verbose' },
            credentials: 'same-origin',
        });
        const text = await res.text();
        if (!res.ok) {
            const err = new Error('HTTP ' + res.status);
            err.status = res.status;
            throw err;
        }
        return JSON.parse(text);
    }

    async function fetchAllResults(firstUrl) {
        const all = [];
        let url = firstUrl;
        while (url) {
            const data = await fetchJson(url);
            const d = data && data.d;
            const results = (d && d.results) || [];
            all.push(...results);
            url = (d && d.__next) || null;
        }
        return all;
    }

    // v9.135.0：詳細表示の追加列（作成日時・作成者・バージョン・チェックアウト）の取得段階。
    //  取得できない環境では、項目を減らして再試行し、以後はその段階から始める（Files: 2→1→0／Folders: 1→0）
    var osxChildExtraLv = { Files: 2, Folders: 1 };
    // v11.43.114：取得の学習値をブラウザに保存する。この環境で失敗する問い合わせ
    // （$expand 系）は、ページを再読み込みしても踏み直さない。学習は30日で切れて再確認する。
    var osxCaps = (() => { const c = osxLs.getJson('osx_child_caps_v1', null); return (c && (Date.now() - (c.at || 0)) < 30 * 86400000) ? c : null; })();
    if (osxCaps) {
        if (typeof osxCaps.fx === 'number') osxChildExtraLv.Files = osxCaps.fx;
        if (typeof osxCaps.fo === 'number') osxChildExtraLv.Folders = osxCaps.fo;
    }
    var osxChildUserOk = { Files: !(osxCaps && osxCaps.fu === 0), Folders: !(osxCaps && osxCaps.ou === 0) };
    var osxAuthorBulkNg = new Set((osxCaps && Array.isArray(osxCaps.ab)) ? osxCaps.ab : []);
    var osxLibTitleCache = new Map();      // ライブラリのタイトル（セッション内）
    var osxUserNameCache = new Map();      // サイト＋ユーザーID→名前（セッション内）
    function osxCapsSave() {
        osxLs.setJson('osx_child_caps_v1', { fx: osxChildExtraLv.Files, fo: osxChildExtraLv.Folders, fu: osxChildUserOk.Files ? 1 : 0, ou: osxChildUserOk.Folders ? 1 : 0, ab: [...osxAuthorBulkNg].slice(0, 20), at: Date.now() });
    }
    var osxAuthorFillTried = new Set();
    var osxFolderAuthorCache = new Map();   // v11.43.115：フォルダの作成者・更新者・作成日時（セッション内で右エリアと窓が共用）   // フォルダ作成者の予備ルートを試したフォルダ（セッション内）
    function folderChildUrl(siteUrl, folderPath, child, usePathApi, withUser, extra) {
        const escaped = folderPath.replace(/'/g, "''");
        // v9.66：withUser=true のとき更新者（フォルダ＝ListItemAllFields/Editor、ファイル＝ModifiedBy）も取得
        let select = child === 'Folders'
            ? 'Name,ServerRelativeUrl,ItemCount,TimeLastModified,UniqueId'
            : 'Name,ServerRelativeUrl,TimeLastModified,Length,LinkingUrl,UniqueId';   // v11.43.28：UniqueId は File／Folder の直接プロパティ（残像の実体判定用）
        let expand = '';
        if (withUser) {
            if (child === 'Folders') {
                select += ',ListItemAllFields/Editor/Title'; expand = '&$expand=ListItemAllFields/Editor';
                if (extra) { select += ',TimeCreated,ListItemAllFields/Author/Title'; expand = '&$expand=ListItemAllFields/Editor,ListItemAllFields/Author'; }
            } else {
                select += ',ModifiedBy/Title'; expand = '&$expand=ModifiedBy';
                if (extra) {
                    select += ',TimeCreated,UIVersionLabel,CheckOutType,Author/Title'; expand = '&$expand=ModifiedBy,Author';
                    if (extra >= 2) { select += ',CheckedOutByUser/Title'; expand += ',CheckedOutByUser'; }
                }
            }
        }
        if (usePathApi) {
            return `${siteUrl}/_api/web/GetFolderByServerRelativePath(decodedurl='${escaped}')/${child}?$select=${select}${expand}&$top=${PAGE_SIZE}`;
        }
        const encodedParam = encodeURIComponent(`'${escaped}'`);
        return `${siteUrl}/_api/web/GetFolderByServerRelativeUrl(@f)/${child}?@f=${encodedParam}&$select=${select}${expand}&$top=${PAGE_SIZE}`;
    }

    async function fetchChildItemsOnce(ctx, child, withUser, extra) {
        try {
            return await fetchAllResults(folderChildUrl(ctx.siteUrl, ctx.folderPath, child, true, withUser, extra));
        } catch (e) {
            if (e && (e.status === 400 || e.status === 404)) {
                return await fetchAllResults(folderChildUrl(ctx.siteUrl, ctx.folderPath, child, false, withUser, extra));
            }
            throw e;
        }
    }

    // v9.66：opts.withUser=true なら更新者付きで取得し、失敗した場合は更新者なしで再取得する

    // フォルダの作成者・作成日時が通常取得で欠けた環境向けの予備ルート：
    //   一覧表示は待たせず、開いているフォルダ直下のフォルダ分だけをリスト項目の窓口から
    //   まとめて1回（＋リスト特定1回）で取得し、届いたら行へ後から埋める。失敗しても無言で終える。
    // v11.43.117：後埋めは非同期の脇役処理。内部で何が起きても、呼び出し側へ例外を漏らさない保証を付ける
    async function osxFillFolderAuthors(ctx, rawFolders, target) {
        try { await osxFillFolderAuthorsInner(ctx, rawFolders, target); } catch (e) { osxDbg('osxFillFolderAuthors', e); }
    }
    async function osxFillFolderAuthorsInner(ctx, rawFolders, target) {
        const missing = (rawFolders || []).filter((f) => !(f.ListItemAllFields && f.ListItemAllFields.Author));
        if (!missing.length) return;
        // v11.43.115：埋める先は呼び出し側の一覧（右エリア／フォルダ窓）。既定は右エリア
        const tgtApps = (target && target.apps) || autoFolderApps;
        const stillHere = (target && target.stillHere) || (() => { const n = getCurrentFolderContext(); return n && n.folderPath === ctx.folderPath; });
        const applyMap = (byRef) => {
            let changed = 0;
            tgtApps.forEach((app) => {
                if (app.kind !== 'folder') return;
                const it = byRef.get(app._serverRelativeUrl);
                if (!it) return;
                if (!app._createdBy && it.Author && it.Author.Title) { app._createdBy = it.Author.Title; changed++; }
                if (!app._modifiedBy && it.Editor && it.Editor.Title) { app._modifiedBy = it.Editor.Title; changed++; }
                if (!app._created && it.Created) { app._created = it.Created; changed++; }
            });
            if (changed && stillHere()) { if (target && target.apply) target.apply(); else { sortAutoFolderApps(); rebuildAutoIcons(); } }
            return changed;
        };
        // v11.43.115：このセッションで取得済みの分は、通信せず即埋める（右エリアと窓で共用）
        const cachedMap = new Map();
        missing.forEach((f) => { const c = osxFolderAuthorCache.get(f.ServerRelativeUrl); if (c) cachedMap.set(f.ServerRelativeUrl, c); });
        if (cachedMap.size) applyMap(cachedMap);
        if (cachedMap.size === missing.length) return;
        if (osxAuthorFillTried.has(ctx.folderPath)) return;
        osxAuthorFillTried.add(ctx.folderPath);
        // 作成者の「名前」は AuthorId（ただの数値）から別に引く。Person項目の展開（$expand=Author）は
        // 環境によってエラーになるため、この予備ルートでは一切使わない。
        const resolveName = async (id) => {
            if (id == null || id === '') return '';
            const nkey = ctx.siteUrl + '#' + id;   // v11.43.114：名前引きはセッション内で使い回す
            if (osxUserNameCache.has(nkey)) return osxUserNameCache.get(nkey);
            let name = '';
            try {
                const r = await spRestRequest(ctx.siteUrl, `/_api/web/siteusers/getbyid(${Number(id)})?$select=Title`, { method: 'GET' });
                name = (r && r.d && r.d.Title) || '';
            } catch (e) { /* 名前が引けない場合は空のまま */ }
            osxUserNameCache.set(nkey, name);
            return name;
        };
        const applyPairs = async (pairs) => { const byRef = await withNames(pairs); byRef.forEach((v, k) => osxFolderAuthorCache.set(k, v)); return applyMap(byRef); };
        const withNames = async (pairs) => {
            const ids = [...new Set(pairs.flatMap((p) => [p.authorId, p.editorId]).filter((v) => v != null && v !== ''))].slice(0, 16);
            for (const id of ids) await resolveName(id);
            const byRef = new Map();
            pairs.forEach((p) => { byRef.set(p.ref, { Author: { Title: osxUserNameCache.get(ctx.siteUrl + '#' + p.authorId) || '' }, Editor: { Title: osxUserNameCache.get(ctx.siteUrl + '#' + p.editorId) || '' }, Created: p.created }); });
            return byRef;
        };
        const odata = (s) => String(s || '').replace(/'/g, "''");
        const urlSafe = (s) => String(s || '').replace(/%/g, '%25').replace(/#/g, '%23');
        const sitePath = new URL(ctx.siteUrl).pathname.replace(/\/$/, '');
        const rel = ctx.folderPath.startsWith(sitePath + '/') ? ctx.folderPath.slice(sitePath.length + 1) : '';
        const libRoot = rel ? sitePath + '/' + rel.split('/')[0] : ctx.folderPath;
        // ---- リスト（ライブラリ）の特定：3つの手段を順に試す ----
        let title = osxLibTitleCache.get(libRoot) || '';
        if (!title) try {
            const r = await spRestRequest(ctx.siteUrl, `/_api/web/GetListUsingPath(DecodedUrl=@p)?@p=${apiQuotedPath(libRoot)}&$select=Title`, { method: 'GET' });
            title = (r && r.d && r.d.Title) || '';
        } catch (e) { /* 次の手段へ */ }
        if (!title) {
            try {
                const r = await spRestRequest(ctx.siteUrl, `/_api/web/lists?$select=Title,RootFolder/ServerRelativeUrl&$expand=RootFolder`, { method: 'GET' });
                const hit = (((r && r.d && r.d.results) || [])).find((x) => x.RootFolder && x.RootFolder.ServerRelativeUrl === libRoot);
                title = (hit && hit.Title) || '';
            } catch (e) { /* 次の手段へ */ }
        }
        if (!title) {
            try {
                const r2 = await spRestRequest(ctx.siteUrl, `/_api/web/${spFolderFn(ctx.folderPath)}/ListItemAllFields/ParentList?@p=${apiQuotedPath(ctx.folderPath)}&$select=Title`, { method: 'GET' });
                title = (r2 && r2.d && r2.d.Title) || '';
            } catch (e) { /* 次の手段へ */ }
        }
        if (title) osxLibTitleCache.set(libRoot, title);
        // ---- まとめて取得：AuthorId だけ取る（Person展開なし）。絞り込みは2通り ----
        if (title && !osxAuthorBulkNg.has(libRoot)) {
            const base = `${ctx.siteUrl}/_api/web/lists/getbytitle('${odata(urlSafe(title))}')/items?$select=FileLeafRef,FileRef,Created,AuthorId,EditorId&$top=500`;
            const filters = [
                `FSObjType eq 1 and FileDirRef eq '${odata(urlSafe(ctx.folderPath))}'`,
                `FileDirRef eq '${odata(urlSafe(ctx.folderPath))}'`,
            ];
            let bulkThrew = 0;
            for (const flt of filters) {
                try {
                    const r = await spRestRequest(ctx.siteUrl, base.replace(ctx.siteUrl, '') + '&$filter=' + flt, { method: 'GET' });
                    const items = (r && r.d && r.d.results) || [];
                    const pairs = items.filter((it) => it.FileRef && it.FileRef.slice(0, it.FileRef.length - (it.FileLeafRef || '').length - 1) === ctx.folderPath)
                        .map((it) => ({ ref: it.FileRef, authorId: it.AuthorId, editorId: it.EditorId, created: it.Created }));
                    if (pairs.length && (await applyPairs(pairs)) > 0) { return; }
                } catch (e) { bulkThrew++; /* 次の手段へ */ }
            }
            // v11.43.114：絞り込み取得が両方とも拒まれたライブラリ（表示しきい値など）では、
            // 次から試さず単品取得へ直行する（学習はブラウザに保存する）
            if (bulkThrew === filters.length) { osxAuthorBulkNg.add(libRoot); osxCapsSave(); }
        }
        // ---- 最後の手段：欠けたフォルダだけを1件ずつ（最大60件・4件ずつ並行、Person展開なし） ----
        let okN = 0, ngN = 0, firstErr = '';
        try {
            const targets = missing.filter((f) => !osxFolderAuthorCache.has(f.ServerRelativeUrl)).slice(0, 60);
            const pairs = [];
            for (let i = 0; i < targets.length; i += 4) {
                if (!stillHere()) return;
                await Promise.all(targets.slice(i, i + 4).map(async (f) => {
                    try {
                        const r = await spRestRequest(ctx.siteUrl, `/_api/web/${spFolderFn(f.ServerRelativeUrl)}/ListItemAllFields?@p=${apiQuotedPath(f.ServerRelativeUrl)}&$select=Created,AuthorId,EditorId`, { method: 'GET' });
                        const d = (r && r.d) || {};
                        pairs.push({ ref: f.ServerRelativeUrl, authorId: d.AuthorId, editorId: d.EditorId, created: d.Created });
                        okN++;
                    } catch (err) { ngN++; if (!firstErr) firstErr = (err && err.message) || String(err); }
                }));
            }
            if (pairs.length && (await applyPairs(pairs)) > 0) { return; }
        } catch (e2) { /* ここまで来たら本当に取れない */ }
        osxAuthorFillTried.delete(ctx.folderPath);
    }
    async function fetchChildItems(ctx, child, opts) {
        if (opts && opts.withUser && osxChildUserOk[child]) {
            let triedExtra = false;
            if (opts.extra) {
                for (let lv = osxChildExtraLv[child] || 0; lv >= 1; lv--) {
                    triedExtra = true;
                    try {
                        const r = await fetchChildItemsOnce(ctx, child, true, lv);
                        if (osxChildExtraLv[child] !== lv) { osxChildExtraLv[child] = lv; osxCapsSave(); }
                        return r;
                    } catch (e) {
                        if (e && (e.status === 401 || e.status === 403)) throw e;   // 権限なしは項目を減らしても同じ
                        /* 追加項目を減らして再試行 */
                    }
                }
            }
            try {
                const r = await fetchChildItemsOnce(ctx, child, true);
                if (triedExtra) { osxChildExtraLv[child] = 0; osxCapsSave(); }   // 追加項目を付けると失敗する環境：以後は付けない（学習を保存する）
                return r;
            } catch (e) {
                if (e && (e.status === 401 || e.status === 403)) throw e;
                // 問い合わせの形自体をサーバーが拒む（400／404）なら、この環境では更新者つき取得は
                // 使えないと学習して保存する。以後は素の取得から入り、作成者・更新者は予備ルートが埋める。
                if (e && (e.status === 400 || e.status === 404)) { osxChildUserOk[child] = false; osxCapsSave(); }
                /* 更新者なしで再試行 */
            }
        }
        return await fetchChildItemsOnce(ctx, child, false);
    }

    function buildItemPageUrl(ctx, serverRelativeUrl, isFile, linkingUrl) {
        if (isFile) {
            if (linkingUrl) return linkingUrl;
            return ctx.origin + encodeServerRelativeUrl(serverRelativeUrl);
        }
        if (ctx.listViewPathname) {
            const pageUrl = new URL(ctx.origin + ctx.listViewPathname);
            if (ctx.viewId) pageUrl.searchParams.set('viewid', ctx.viewId);
            pageUrl.searchParams.set('id', serverRelativeUrl);
            return pageUrl.toString();
        }
        return ctx.origin + encodeServerRelativeUrl(serverRelativeUrl);
    }

    function buildAutoFolderApp(ctx, folderInfo) {
        return {
            id: 'auto_' + folderInfo.ServerRelativeUrl,
            icon: AUTO_FOLDER_ICON,
            iconSvg: FOLDER_ICON_SVG,
            label: folderInfo.Name,
            title: `${AUTO_FOLDER_ICON} ${folderInfo.Name}`,
            url: buildItemPageUrl(ctx, folderInfo.ServerRelativeUrl, false),
            blocked: true,
            kind: 'folder',
            _serverRelativeUrl: folderInfo.ServerRelativeUrl,
            _uid: folderInfo.UniqueId || '',   // v11.43.25：残像の実体判定
            _lastModified: folderInfo.TimeLastModified,
            _itemCount: folderInfo.ItemCount,
            _modifiedBy: (folderInfo.ListItemAllFields && folderInfo.ListItemAllFields.Editor && folderInfo.ListItemAllFields.Editor.Title) || '',
            _created: folderInfo.TimeCreated || '',
            _createdBy: (folderInfo.ListItemAllFields && folderInfo.ListItemAllFields.Author && folderInfo.ListItemAllFields.Author.Title) || '',
        };
    }

    function buildAutoFileApp(ctx, fileInfo) {
        const icon = fileIcon(fileInfo.Name);
        return {
            id: 'auto_file_' + fileInfo.ServerRelativeUrl,
            icon,
            iconSvg: fileIconSvg(fileInfo.Name),
            label: fileInfo.Name,
            title: `${icon} ${fileInfo.Name}`,
            url: buildItemPageUrl(ctx, fileInfo.ServerRelativeUrl, true, fileInfo.LinkingUrl),
            blocked: true,
            kind: 'file',
            _serverRelativeUrl: fileInfo.ServerRelativeUrl,
            _uid: fileInfo.UniqueId || '',   // v11.43.25：残像の実体判定
            _lastModified: fileInfo.TimeLastModified,
            _itemCount: fileInfo.Length,
            _modifiedBy: (fileInfo.ModifiedBy && fileInfo.ModifiedBy.Title) || '',
            _created: fileInfo.TimeCreated || '',
            _createdBy: (fileInfo.Author && fileInfo.Author.Title) || '',
            _version: fileInfo.UIVersionLabel || '',
            _checkout: (() => {
                const co = Number(fileInfo.CheckOutType);   // 0=オンライン／1=オフライン／2=なし
                if (co !== 0 && co !== 1) return '';
                return '🔒 ' + ((fileInfo.CheckedOutByUser && fileInfo.CheckedOutByUser.Title) || 'チェックアウト中');
            })(),
        };
    }

    function setFolderLabel(text, spinning) {
        folderLabelEl.replaceChildren();
        if (spinning) {
            const spin = document.createElement('span');
            spin.className = 'os-folder-spinner';
            folderLabelEl.appendChild(spin);
        }
        folderLabelEl.appendChild(document.createTextNode(text));
    }

    let autoFolderRequestSeq = 0;
    async function refreshAutoFolders() {
        // v11.43.24：実フォルダの再取得が来たら、入口がどこでもZIP表示を終える。
        // パンくず（ZIPがあるフォルダ自身を含む）・戻る／進む・フォルダのダブルクリック・ショートカットは
        // すべてここを通る。「実フォルダを見せる」という操作の意味と、ZIP表示が食い違うため。
        // （ZIP内での移動は osxZipRender が直接描くので、ここを通らない）
        if (osxZipView) osxZipView = null;
        let ctx = getCurrentFolderContext();
        if (ctx && ctx.needsLibResolve) {
            // v9.61：サイトトップ等では、まず既定ドキュメントライブラリを判定してから一覧を取得する
            const mySeq0 = autoFolderRequestSeq + 1;
            setFolderLabel('ドキュメントライブラリを確認中…', true);
            await ensureDefaultLibrary(ctx.siteUrl);
            if (autoFolderRequestSeq + 1 !== mySeq0) return;
            ctx = getCurrentFolderContext();
        }
        if (customCurrentFolderPath && ctx) syncAddressBarToCurrentFolder(ctx);
        if (ctx && ctx.folderPath !== autoPrevPath) {   // v11.43.115：フォルダを移ったら絞り込みを解除（窓と同じ。同じフォルダの更新では維持）
            autoPrevPath = ctx.folderPath;
            if (autoFilter) { autoFilter = ''; if (autoFilterEl) autoFilterEl.value = ''; }
        }
        renderBreadcrumb();
        const mySeq = ++autoFolderRequestSeq;
        if (!ctx) {
            osxAutoEmptyFolder = false;
            setFolderLabel(IS_OD_SHELL ? '⚠ OneDriveの場所を確認中…（しばらく待っても出ないときは、画面を再読み込みしてください）' : '');
            if (IS_OD_SHELL && odRetryCount < 15) {
                odRetryCount++;
                setTimeout(() => { if (desktop.style.display !== 'none') refreshAutoFolders(); }, 2000);
            }
            if (autoFolderApps.length) {
                autoFolderApps = [];
                rebuildAutoIcons();
                rebuildStartMenuGroups();
            }
            return;
        }
        setFolderLabel('現在のフォルダを取得中…', true);
        try {
            const folders = (await fetchChildItems(ctx, 'Folders', { withUser: true, extra: true })).filter((f) => !isSystemFolder(f.Name));
            let files = [];
            if (showFiles) {
                files = (await fetchChildItems(ctx, 'Files', { withUser: true, extra: true })).filter((f) => !isSkippedFile(f.Name) && !(hideTemp && isTempFile(f.Name)));
            }
            if (mySeq !== autoFolderRequestSeq) return;
            osxAutoEmptyFolder = (folders.length + files.length) === 0;
            autoFolderApps = [
                ...folders.map((f) => buildAutoFolderApp(ctx, f)),
                ...files.map((f) => buildAutoFileApp(ctx, f)),
            ];
            sortAutoFolderApps();
            if (mySeq !== autoFolderRequestSeq) return;
            rebuildAutoIcons();
            rebuildStartMenuGroups();
            osxFillFolderAuthors(ctx, folders);
            try { osxBcTreeOnNavigate(); } catch (e) { osxDbg('osxBcTreeOnNavigate', e); }
            const extra = showFiles ? `／ファイル${files.length}件` : '';
            setFolderLabel(`📂 このフォルダを自動表示中（フォルダ${folders.length}件${extra}）`);
        } catch (e) {
            if (mySeq !== autoFolderRequestSeq) return;
            osxAutoEmptyFolder = false;
            autoFolderApps = [];
            rebuildAutoIcons();
            rebuildStartMenuGroups();
            if (/^\/personal\//i.test(ctx.folderPath) && typeof GM_xmlhttpRequest !== 'function') {
                setFolderLabel('⚠ 個人OneDriveを読むには、Tampermonkeyの権限（@grant GM_xmlhttpRequest）が必要です。このスクリプトを丸ごと入れ替えてください');
                return;
            }
            const denied = e && (e.status === 401 || e.status === 403);
            setFolderLabel(denied
                ? `🔒 ${ctx.folderPath.split('/').pop()}（この場所へのアクセス権がありません。上位階層が閲覧不可の場合は、開ける階層のショートカットから開いてください）`
                : `📂 ${ctx.folderPath.split('/').pop()}（表示対象アイテムなし／またはAPI制限）`);
        }
    }

