            if (ext !== 'xlsx' && ext !== 'xlsm') { lgSelfErr = '対象外：' + ext; return null; }
            const bytes = await fetchFileBytesForViewer({ label: app.label, url: app.url, _serverRelativeUrl: app._serverRelativeUrl, rawServerRelativeUrl: app._serverRelativeUrl });
            if (!bytes || !bytes.length || bytes.length > 12 * 1024 * 1024) { lgSelfErr = stage + '（応答なし／大きすぎ）'; return null; }
            stage = 'zip展開';
            const zip = await lgZipOpen(bytes);
            if (!zip) { lgSelfErr = stage; return null; }
            const wb = await zip.text('xl/workbook.xml');
            const rels = await zip.text('xl/_rels/workbook.xml.rels');
            if (!wb || !rels) { lgSelfErr = stage + '（中身なし）'; return null; }
            const sheetTags = [...wb.matchAll(/<sheet(?=[\s/>])[^>]*>/g)].map((m) => m[0]);
            if (!sheetTags.length) { lgSelfErr = 'シート特定（シートなし）'; return null; }
            const activeM = wb.match(/<workbookView[^>]*activeTab="(\d+)"/);
            const sheetTag = sheetTags[Math.min(sheetTags.length - 1, activeM ? +activeM[1] : 0)];
            const rid = lgXlAttr(sheetTag, 'r:id');
            let target = null;
            for (const m of rels.matchAll(/<Relationship(?=[\s/>])[^>]*>/g)) { if (lgXlAttr(m[0], 'Id') === rid) { target = lgXlAttr(m[0], 'Target'); break; } }
            if (!target) { lgSelfErr = 'シート特定（対応表なし）'; return null; }
            const sheetPath = target.startsWith('/') ? target.slice(1) : 'xl/' + target.replace(/^\.\//, '').replace(/^xl\//, '');
            const sheetXml = await zip.text(sheetPath);
            const stylesXml = await zip.text('xl/styles.xml');
            if (!sheetXml || !stylesXml) { lgSelfErr = stage + '（シートなし）'; return null; }
            const sharedXml = await zip.text('xl/sharedStrings.xml');
