            // v9.140.1：ドックはアイコンの位置に合わせてバー自体が山なりに盛り上がる（アイコンも山の上に乗る）。アイコンは無彩色
            dock.style.setProperty('--n', String(dockBtns.length || 1));
            dockBtns.forEach((b) => { const n = b.firstChild; if (n && n.nodeType === 3) { const sp = mk('span', 'ic'); sp.textContent = n.textContent; b.replaceChild(sp, n); } });
            const SVGNS = 'http://www.w3.org/2000/svg', HILL = 46;
            const dkSvg = document.createElementNS(SVGNS, 'svg'), dkPath = document.createElementNS(SVGNS, 'path');
            dkSvg.setAttribute('class', 'g3-dkbg'); dkSvg.setAttribute('aria-hidden', 'true'); dkSvg.appendChild(dkPath);
            dock.insertBefore(dkSvg, dock.firstChild);
            const dk = { x: 0, tx: 0, a: 0, ta: 0, raf: 0, w: 0 };
            function dockDraw() {
                const W = dock.offsetWidth, H = dock.offsetHeight; if (!W) return;
                if (dk.w !== W) { dk.w = W; dkSvg.setAttribute('width', W); dkSvg.setAttribute('height', H + HILL); dkSvg.setAttribute('viewBox', '0 0 ' + W + ' ' + (H + HILL)); dkSvg.style.top = (-HILL) + 'px'; }
                const R = 18, top = HILL, g = (d, sg) => Math.exp(-(d * d) / (2 * sg * sg)), tp = (x) => { const t = Math.max(0, Math.min(1, Math.min(x - R, W - R - x) / 40)); return t * t * (3 - 2 * t); };
                let d = 'M0,' + (top + R) + ' Q0,' + top + ' ' + R + ',' + top;
                for (let x = R + 4; x < W - R; x += 4) d += ' L' + x + ',' + (top - HILL * 0.9 * dk.a * g(x - dk.x, 62) * tp(x)).toFixed(2);
                d += ' L' + (W - R) + ',' + top + ' Q' + W + ',' + top + ' ' + W + ',' + (top + R) + ' L' + W + ',' + (top + H - R) + ' Q' + W + ',' + (top + H) + ' ' + (W - R) + ',' + (top + H) + ' L' + R + ',' + (top + H) + ' Q0,' + (top + H) + ' 0,' + (top + H - R) + ' Z';
                dkPath.setAttribute('d', d);
                const dr = dock.getBoundingClientRect();
                dockBtns.forEach((b) => {
                    const r = b.getBoundingClientRect(), cx = r.left - dr.left + r.width / 2, k = g(cx - dk.x, 50) * dk.a * tp(cx);
                    b.style.transform = k < 0.004 ? '' : 'translateY(' + (-(HILL * 0.9) * k * 0.62).toFixed(2) + 'px) scale(' + (1 + 0.5 * k).toFixed(3) + ')';
                });
            }
