                dk.a += (dk.ta - dk.a) * 0.22; dk.x += (dk.tx - dk.x) * 0.35;
                if (Math.abs(dk.ta - dk.a) < 0.004) dk.a = dk.ta;
                dockDraw();
                if (dk.a !== dk.ta || Math.abs(dk.tx - dk.x) > 0.5) dk.raf = requestAnimationFrame(dockStep);
