            dock.addEventListener('pointermove', (e) => { const r = dock.getBoundingClientRect(); dk.tx = e.clientX - r.left; if (dk.ta === 0) dk.x = dk.tx; dk.ta = RM ? 0 : 1; dockKick(); });
            dock.addEventListener('pointerleave', () => { dk.ta = 0; dockKick(); });
