            // ---------- v9.144.0：メニューパネルの自動表示（マウスが近づくと浮き出す） ----------
            const topEl = $('.g3-top');
            const AUTO = [[topEl, 64], [leftEl, 80], [info, 72], [dock, 84], [pager, 56]];
            const autoOn = !(window.matchMedia && matchMedia('(hover: none)').matches);
            const peekT = new Map();
            function peekShow(el) { if (!el) return; const t = peekT.get(el); if (t) { clearTimeout(t); peekT.delete(el); } el.classList.add('show'); }
            function peekKeep(el) {
                const ae = document.activeElement;
                if (ae && el.contains(ae) && /^(INPUT|SELECT|TEXTAREA)$/.test(ae.tagName)) return true;
                if (el === leftEl && (leftEl.classList.contains('dropok') || OSX_API_3D.draggingAutoApp)) return true;
                if (contextMenu.classList.contains('active')) return true;
                return false;
            }
