                ov.addEventListener('focusout', (e) => { const a = AUTO.find(([el]) => el.contains(e.target)); if (a) peekHideLater(a[0], 700); });
                // ドラッグ中は pointermove が来ないので dragover で追従（左パネルへのドロップ用）
